import std.collection.HashMap
import std.time.DateTime

class AccessGatewayFilter {
    /*
    This class is a filter used for accessing gateway filtering, primarily for authentication and access log recording.
    */

    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        let path = request.get("path") ?? ""
        let method = request.get("method") ?? ""

        // Allow direct access to /login via POST
        if (method == "POST" && path == "/login") {
            return true
        }

        // Check if path starts with allowed prefixes
        if (!is_start_with(path)) {
            return false
        }

        // For other paths, validate JWT token
        let user_option = get_jwt_user(request)
        if (user_option is Some<HashMap<String, Any>>) {
            let user = user_option.getOrThrow()
            set_current_user_info_and_log(user)
            return true
        }

        return false
    }

    public func is_start_with(request_uri: String): Bool {
        if (request_uri.startsWith("/api") || request_uri.startsWith("/login")) {
            return true
        }
        return false
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers_option = request.get("headers")
        if (headers_option is None<String>) {
            return None<HashMap<String, Any>>
        }
        let headers = headers_option as HashMap<String, Any>

        let auth_option = headers.get("Authorization")
        if (auth_option is None<HashMap<String, Any>>) {
            return None<HashMap<String, Any>>
        }
        let auth = auth_option as HashMap<String, Any>

        let jwt = auth.get("jwt") as? String
        let user = auth.get("user") as? HashMap<String, Any>

        // Simple JWT validation: check if jwt contains current date
        if (jwt != null && user != null && jwt.contains(DateTime.now().format("yyyy-MM-dd"))) {
            return Some<HashMap<String, Any>>(user)
        }

        return None<HashMap<String, Any>>
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        let username = user.get("name") ?? "unknown"
        let address = user.get("address") ?? "unknown"
        let timestamp = DateTime.now().format("yyyy-MM-dd HH:mm:ss")
