import std.collection.HashMap
import std.time.DateTime

class AccessGatewayFilter {
    /*
    This class is a filter used for accessing gateway filtering, primarily for authentication and access log recording.
    */

    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        let path = request.get("path") ?? None<String>
        if (path is None<String>) {
            return false
        }
        let method = request.get("method") ?? None<String>
        if (method is None<String>) {
            return false
        }

        let uri = path.getOrThrow()
        if (!this.is_start_with(uri)) {
            return false
        }

        if (uri == "/login" && method.getOrThrow() == "POST") {
            return true
        }

        let user_option = this.get_jwt_user(request)
        if (user_option is Some<HashMap<String, Any>>) {
            let user = user_option.getOrThrow()
            this.set_current_user_info_and_log(user)
            return true
        }

        return false
    }

    public func is_start_with(request_uri: String): Bool {
        if (request_uri.startsWith("/api") || request_uri.startsWith("/login")) {
            return true
        }
        return false
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers_option = request.get("headers") as? HashMap<String, Any>
        if (headers_option is None<HashMap<String, Any>>) {
            return None<HashMap<String, Any>>
        }
        let headers = headers_option.getOrThrow()

        let auth_option = headers.get("Authorization") as? HashMap<String, Any>
        if (auth_option is None<HashMap<String, Any>>) {
            return None<HashMap<String, Any>>
        }
        let auth = auth_option.getOrThrow()

        let jwt_option = auth.get("jwt") as? String
        let user_option = auth.get("user") as? HashMap<String, Any>

        if (jwt_option is Some<String> && user_option is Some<HashMap<String, Any>>) {
            let jwt = jwt_option.getOrThrow()
            let user = user_option.getOrThrow()
            let expected_jwt_suffix = DateTime.now().format("yyyy-MM-dd")
            if (jwt.endsWith(expected_jwt_suffix)) {
                return Some<HashMap<String, Any>>(user)
            }
        }

        return None<HashMap<String, Any>>
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        let name = user.get("name") ?? "unknown"
        let address = user.get("address") ?? "unknown"
        let timestamp = DateTime.now().format("yyyy-MM-dd HH:mm:ss")
        println("[${timestamp}] User '${name}' from ${address} accessed the gateway.")
    }
}

