        >>> parser.required
        {'arg1'}
        >>> parser.types
        {'arg1': Int64}
        */
        types.add(arg, arg_type)
        if (required) {
            this.required.add(arg)
        }
    }

    public func convert_type(arg: String, value: String): Any {
        /*
        Try to convert the type of input value by searching in this.types.
        :param value: String, the input value in command line
        :return: return corresponding value in this.types if convert successfully, or the input value otherwise
        >>> parser.types
        {'arg1': Int64}
        >>> parser._convert_type('arg1', '21')
        21
        */
        let t = types.get(arg) ?? None<TypeInfo>
        if (t is Some<TypeInfo>) {
            let type_info = t.getOrThrow()
            if (type_info == TypeInfo.of<Int64>()) {
                let parsed = value.toInt()
                return if (parsed is Some<Int64>) { parsed.getOrThrow() } else { value }
            } else if (type_info == TypeInfo.of<Float64>()) {
                let parsed = value.toFloat()
                return if (parsed is Some<Float64>) { parsed.getOrThrow() } else { value }
            } else if (type_info == TypeInfo.of<Bool>()) {
                return value.lower() in ["true", "1", "yes"]
            }
        }
        return value
    }
