import std.collection.*
import std.convert.Parsable

class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    // Helper: check if a string represents a negative number
    private static func isNegative(s: String): Bool {
        return s[0] == '-'
    }

    // Helper: remove sign for processing
    private static func stripSign(s: String): String {
        return if (isNegative(s)) { s.substring(1) } else { s }
    }

    // Helper: compare two absolute values (as strings), returns true if |a| > |b|
    private static func absGreaterThan(a: String, b: String): Bool {
        let aClean = stripSign(a)
        let bClean = stripSign(b)
        if (aClean.size != bClean.size) {
            return aClean.size > bClean.size
        }
        return aClean > bClean  // lexicographical comparison works for same-length numbers
    }

    // Helper: add two positive number strings
    private static func addPositive(a: String, b: String): String {
        let aRunes = stripSign(a).runes().toList().reverse()
        let bRunes = stripSign(b).runes().toList().reverse()
        var result = ArrayList<Rune>()
        var carry = 0
        let maxSize = max(aRunes.size, bRunes.size)

        for (i in 0..maxSize) {
            let digitA = if (i < aRunes.size) { aRunes[i].toInt() - '0'.toInt() } else { 0 }
            let digitB = if (i < bRunes.size) { bRunes[i].toInt() - '0'.toInt() } else { 0 }
            let total = digitA + digitB + carry
            result.add((total % 10).toRune(), at: 0)  // prepend
            carry = total / 10
        }

        if (carry > 0) {
            result.add(carry.toRune(), at: 0)
        }

        return String(result.toArray())
    }

    // Helper: subtract two positive number strings (|a| >= |b|)
    private static func subtractPositive(a: String, b: String): String {
        let aRunes = stripSign(a).runes().toList().reverse()
        let bRunes = stripSign(b).runes().toList().reverse()
        var result = ArrayList<Rune>()
        var borrow = 0

        for (i in 0..aRunes.size) {
            let digitA = if (i < aRunes.size) { aRunes[i].toInt() - '0'.toInt() } else { 0 }
            let digitB = if (i < bRunes.size) { bRunes[i].toInt() - '0'.toInt() } else { 0 }
            let mut adjustedA = digitA - borrow
            borrow = 0
            if (adjustedA < digitB) {
                adjustedA += 10
                borrow = 1
            }
            let diff = adjustedA - digitB
            if (i < aRunes.size || diff > 0) {
                result.add(diff.toRune(), at: 0)
            }
        }

        // Handle all zeros
        if (result.size == 0) {
            return "0"
        }

        return String(result.toArray())
    }

    public static func add(num1: String, num2: String): String {
        if (isNegative(num1) && isNegative(num2)) {
            return "-" + addPositive(num1, num2)
        } else if (isNegative(num1)) {
            return subtract(num2, stripSign(num1))
        } else if (isNegative(num2)) {
            return subtract(num1, stripSign(num2))
        } else {
            return addPositive(num1, num2)
        }
    }

    public static func subtract(num1: String, num2: String): String {
        if (isNegative(num1) && isNegative(num2)) {
            // (-a) - (-b) = b - a
            return subtract(stripSign(num2), stripSign(num1))
        } else if (isNegative(num1)) {
            // (-a) - b = -(a + b)
            return "-" + addPositive(stripSign(num1), num2)
        } else if (isNegative(num2)) {
            // a - (-b) = a + b
            return add(num1, stripSign(num2))
        } else {
            // a - b
            if (absGreaterThan(num2, num1)) {
                return "-" + subtractPositive(num2, num1)
            } else {
                let res = subtractPositive(num1, num2)
                return if (res == "0") { "0" } else { res }
            }
        }
    }

    public static func multiply(num1: String, num2: String): String {
        let negative = isNegative(num1) != isNegative(num2)
        let a = stripSign(num1)
        let b = stripSign(num2)

        let aRunes = a.runes().toList().reverse()
        let bRunes = b.runes().toList().reverse()
        var result = Array<UInt64>(repeat: 0, times: aRunes.size + bRunes.size)

        for (i in 0..aRunes.size) {
            for (j in 0..bRunes.size) {
                let digitA = aRunes[i].toInt() - '0'.toInt()
                let digitB = bRunes[j].toInt() - '0'.toInt()
                result[i + j] += digitA * digitB
            }
        }

        var carry = 0
        for (i in 0..result.size) {
            let total = result[i] + carry
            result[i] = total % 10
            carry = total / 10
        }

        // Convert result to string
        var strResult = ArrayList<Rune>()
        var leading = true
        var hasNonZero = false
        for (i in result.size-1..-1:-1) {
            if (leading && result[i] == 0) {
                continue
            } else {
                leading = false
                hasNonZero = true
                strResult.add(result[i].toRune())
            }
        }

        if (!hasNonZero) {
            return "0"
        }

        let final = String(strResult.toArray())
        return if (negative) { "-" + final } else { final }
    }
}

import std.collection.*
