class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    // Helper: check if a number is negative
    private static func isNegative(num: String): Bool {
        num[0] == '-'
    }

    // Helper: compare absolute values of two positive number strings
    private static func absCompare(num1: String, num2: String): Int64 {
        let len1 = num1.size
        let len2 = num2.size
        if (len1 < len2) {
            return -1
        } else if (len1 > len2) {
            return 1
        } else {
            for (i in 0..len1) {
                if (num1[i] < num2[i]) {
                    return -1
                } else if (num1[i] > num2[i]) {
                    return 1
                }
            }
            return 0
        }
    }

    // Helper: strip leading zeros
    private static func stripZeros(s: String): String {
        let n = s.size
        var i = 0
        while (i < n - 1 && s[i] == '0') {
            i = i + 1
        }
        return s.substr(i, n - i)
    }

    public static func add(num1: String, num2: String): String {
        // Handle signs
        let neg1 = isNegative(num1)
        let neg2 = isNegative(num2)
        let abs1 = neg1 ? num1.substr(1, num1.size - 1) : num1
        let abs2 = neg2 ? num2.substr(1, num2.size - 1) : num2

        if (!neg1 && !neg2) {
            // both positive
            return addAbs(abs1, abs2, false)
        } else if (neg1 && neg2) {
            // both negative
            return addAbs(abs1, abs2, true)
        } else if (neg1) {
            // -a + b = b - a
            return subtract(abs2, abs1)
        } else {
            // a + (-b) = a - b
            return subtract(abs1, abs2)
        }
    }

    // Add two absolute values, return result with sign
    private static func addAbs(a: String, b: String, negative: Bool): String {
        let lenA = a.size
        let lenB = b.size
        let maxLen = if (lenA > lenB) { lenA } else { lenB }
        var result = ArrayList<UInt8>()
        var carry = 0
        var i = lenA - 1
        var j = lenB - 1

        while (i >= 0 || j >= 0 || carry > 0) {
            let digitA = if (i >= 0) { a[i] as UInt8 - '0' as UInt8 } else { 0 }
            let digitB = if (j >= 0) { b[j] as UInt8 - '0' as UInt8 } else { 0 }
            let total = digitA + digitB + carry
            result.add(total % 10 as UInt8, at: 0)
            carry = total / 10 as UInt8
            i = i - 1
            j = j - 1
        }

        let resultStr = joinDigits(result)
        let finalStr = if (resultStr == "0") { "0" } else { if (negative) { "-" + resultStr } else { resultStr } }
        return finalStr
    }

    public static func subtract(num1: String, num2: String): String {
        let neg1 = isNegative(num1)
        let neg2 = isNegative(num2)
        let abs1 = neg1 ? num1.substr(1, num1.size - 1) : num1
        let abs2 = neg2 ? num2.substr(1, num2.size - 1) : num2

        if (!neg1 && !neg2) {
            // a - b
            let cmp = absCompare(abs1, abs2)
            if (cmp >= 0) {
                let result = subtractAbs(abs1, abs2)
                return if (cmp == 0) { "0" } else { result }
            } else {
                let result = subtractAbs(abs2, abs1)
                return "-" + result
            }
        } else if (neg1 && neg2) {
            // (-a) - (-b) = b - a
            let cmp = absCompare(abs1, abs2)
            if (cmp >= 0) {
                let result = subtractAbs(abs1, abs2)
                return if (cmp == 0) { "0" } else { "-" + result }
            } else {
                return subtractAbs(abs2, abs1)
            }
        } else if (neg1) {
            // -a - b = -(a + b)
            let sum = addAbs(abs1, abs2, false)
            return "-" + sum
        } else {
            // a - (-b) = a + b
            return addAbs(abs1, abs2, false)
        }
    }

    // Subtract two absolute values (assume abs1 >= abs2)
    private static func subtractAbs(larger: String, smaller: String): String {
        let lenL = larger.size
        let lenS = smaller.size
        var result = ArrayList<UInt8>()
        var borrow = 0
        var i = lenL - 1
        var j = lenS - 1

        while (i >= 0) {
            let digitL = larger[i] as UInt8 - '0' as UInt8
            let digitS = if (j >= 0) { smaller[j] as UInt8 - '0' as UInt8 } else { 0 }
            let mut sub = digitL - digitS - borrow
            if (sub < 0) {
                sub = sub + 10
                borrow = 1
            } else {
                borrow = 0
            }
            result.add(sub as UInt8, at: 0)
            i = i - 1
            j = j - 1
        }

        return stripZeros(joinDigits(result))
    }

    public static func multiply(num1: String, num2: String): String {
        let neg1 = isNegative(num1)
        let neg2 = isNegative(num2)
        let abs1 = neg1 ? num1.substr(1, num1.size - 1) : num1
        let abs2 = neg2 ? num2.substr(1, num2.size - 1) : num2

        // If either is zero
        if (abs1 == "0" || abs2 == "0") {
            return "0"
        }

        let len1 = abs1.size
        let len2 = abs2.size
        var result = Array<UInt8>([0] * (len1 + len2))

        for (i in 0..len1) {
            for (j in 0..len2) {
                let mul = (abs1[len1 - 1 - i] as UInt8 - '0' as UInt8) * (abs2[len2 - 1 - j] as UInt8 - '0' as UInt8)
                let sum = mul + result[i + j]
                result[i + j] = sum % 10 as UInt8
                result[i + j + 1] = result[i + j + 1] + sum / 10 as UInt8
            }
        }

        // Convert result array to string
        var k = len1 + len2 - 1
        while (k >= 0 && result[k] == 0) {
            k = k - 1
        }
        if (k < 0) {
            return "0"
        }
        var finalDigits = ArrayList<UInt8>()
        for (idx in k..-1:-1) {
            finalDigits.add(result[idx])
        }

        let productStr = joinDigits(finalDigits)
        let negativeResult = neg1 != neg2
        return if (negativeResult && productStr != "0") { "-" + productStr } else { productStr }
    }

    // Helper: convert digit array/list to string
    private static func joinDigits(digits: ArrayList<UInt8>): String {
        let sb = ArrayList<String>()
        for (d in digits) {
            sb.add(String(d as Int64))
        }
        return String.join("", sb)
    }
}

import std.collection.*
