class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    // Helper: check if a number is negative
    private static func isNegative(num: String): Bool {
        return num[0] == '-'
    }

    // Helper: compare absolute values of two positive number strings
    private static func absCompare(num1: String, num2: String): Int64 {
        let len1 = num1.size
        let len2 = num2.size
        if (len1 < len2) {
            return -1
        } else if (len1 > len2) {
            return 1
        } else {
            for (i in 0..len1) {
                if (num1[i] < num2[i]) {
                    return -1
                } else if (num1[i] > num2[i]) {
                    return 1
                }
            }
            return 0
        }
    }

    // Helper: add two positive integers represented as strings
    private static func absAdd(num1: String, num2: String): String {
        var result = ""
        var i = num1.size - 1
        var j = num2.size - 1
        var carry = 0

        while (i >= 0 || j >= 0 || carry > 0) {
            let digit1 = if (i >= 0) { (num1[i] - '0') } else { 0 }
            let digit2 = if (j >= 0) { (num2[j] - '0') } else { 0 }
            let total = digit1 + digit2 + carry
            result = "${total % 10}${result}"
            carry = total / 10
            i = i - 1
            j = j - 1
        }

        return result
    }

    // Helper: subtract two positive integers (num1 - num2), assuming |num1| >= |num2|
    private static func absSubtract(num1: String, num2: String): String {
        var result = ""
        var i = num1.size - 1
        var j = num2.size - 1
        var borrow = 0

        while (i >= 0) {
            let digit1 = (num1[i] - '0') - borrow
            let digit2 = if (j >= 0) { (num2[j] - '0') } else { 0 }
            var current = digit1 - digit2
            borrow = 0
            if (current < 0) {
                current = current + 10
                borrow = 1
            }
            result = "${current}${result}"
            i = i - 1
            j = j - 1
        }

        // Remove leading zeros
        while (result.size > 1 && result[0] == '0') {
            result = result[1..result.size]
        }

        return result
    }

    public static func add(num1: String, num2: String): String {
        // Case 1: Both positive
        if (!isNegative(num1) && !isNegative(num2)) {
            return absAdd(num1, num2)
        }
        // Case 2: num1 negative, num2 positive → num2 - |num1|
        else if (isNegative(num1) && !isNegative(num2)) {
            let abs1 = num1[1..num1.size]
            let cmp = absCompare(abs1, num2)
            if (cmp == 0) {
                return "0"
            } else if (cmp > 0) {
                return "-${absSubtract(abs1, num2)}"
            } else {
                return absSubtract(num2, abs1)
            }
        }
        // Case 3: num1 positive, num2 negative → num1 - |num2|
        else if (!isNegative(num1) && isNegative(num2)) {
            let abs2 = num2[1..num2.size]
            let cmp = absCompare(num1, abs2)
            if (cmp == 0) {
                return "0"
            } else if (cmp > 0) {
                return absSubtract(num1, abs2)
            } else {
                return "-${absSubtract(abs2, num1)}"
            }
        }
        // Case 4: Both negative → -( |num1| + |num2| )
        else {
            return "-${absAdd(num1[1..num1.size], num2[1..num2.size])}"
        }
    }

    public static func subtract(num1: String, num2: String): String {
        // Subtraction: num1 - num2 = num1 + (-num2)
        if (isNegative(num2)) {
            // -(-a) = a
            return add(num1, num2[1..num2.size])
        } else {
            return add(num1, "-${num2}")
        }
    }

    public static func multiply(num1: String, num2: String): String {
        // Handle signs
        let negative1 = isNegative(num1)
        let negative2 = isNegative(num2)
        let sign = if (negative1 ^ negative2) { "-" } else { "" }

        let abs1 = if (negative1) { num1[1..num1.size] } else { num1 }
        let abs2 = if (negative2) { num2[1..num2.size] } else { num2 }

        // Multiplication by zero
        if (abs1 == "0" || abs2 == "0") {
            return "0"
        }

        // Result array for digits
        let len1 = abs1.size
        let len2 = abs2.size
        var resultDigits = Array<Int64>(len1 + len2, 0)

        // Perform digit multiplication
        for (i in 0..len1) {
            for (j in 0..len2) {
                let digit1 = abs1[len1 - 1 - i] - '0'
                let digit2 = abs2[len2 - 1 - j] - '0'
                resultDigits[i + j] = resultDigits[i + j] + digit1 * digit2
            }
        }

        // Carry over
        var carry = 0
        for (k in 0..resultDigits.size) {
            let total = resultDigits[k] + carry
            resultDigits[k] = total % 10
            carry = total / 10
        }

        // Build result string from digits
        var result = ""
        var started = false
        for (k in 0..resultDigits.size) {
            let idx = resultDigits.size - 1 - k
            if (resultDigits[idx] != 0) {
                started = true
            }
            if (started) {
                result = "${result}${resultDigits[idx]}"
            }
        }

        return "${sign}${result}"
    }

}

