class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    // Helper: check if a number is negative
    private static func isNegative(num: String): Bool {
        return num[0] == '-'
    }

    // Helper: compare absolute values of two positive number strings
    private static func absCompare(num1: String, num2: String): Int64 {
        let len1 = num1.size
        let len2 = num2.size
        if (len1 < len2) {
            return -1
        } else if (len1 > len2) {
            return 1
        } else {
            for (i in 0..len1) {
                if (num1[i] < num2[i]) {
                    return -1
                } else if (num1[i] > num2[i]) {
                    return 1
                }
            }
            return 0
        }
    }

    // Helper: remove leading zeros
    private static func removeLeadingZeros(s: String): String {
        var i = 0
        while (i < s.size && s[i] == '0') {
            i = i + 1
        }
        if (i == s.size) {
            return "0"
        }
        return s[i..s.size]
    }

    public static func add(num1: String, num2: String): String {
        // Handle signs
        if (!isNegative(num1) && !isNegative(num2)) {
            return addPositive(num1, num2)
        } else if (isNegative(num1) && isNegative(num2)) {
            let result = addPositive(num1[1..num1.size], num2[1..num2.size])
            return "-" + result
        } else if (isNegative(num1)) {
            return subtractPositive(num2, num1[1..num1.size])
        } else {
            return subtractPositive(num1, num2[1..num2.size])
        }
    }

    private static func addPositive(a: String, b: String): String {
        let i = a.size - 1
        let j = b.size - 1
        let carry = 0
        let result = ArrayList<UInt8>()

        var ii = i
        var jj = j
        var cc = carry

        while (ii >= 0 || jj >= 0 || cc > 0) {
            let x = if (ii >= 0) { a[ii] - '0' } else { 0 }
            let y = if (jj >= 0) { b[jj] - '0' } else { 0 }
            let sum = x + y + cc
            result.add(sum % 10, at: 0)
            cc = sum / 10
            ii = ii - 1
            jj = jj - 1
        }

        let sb = ArrayList<String>()
        for (digit in result) {
            sb.add(String(digit))
        }
        return removeLeadingZeros(sb.join(""))
    }

    public static func subtract(num1: String, num2: String): String {
        // Handle signs
        if (!isNegative(num1) && !isNegative(num2)) {
            return subtractPositive(num1, num2)
        } else if (isNegative(num1) && isNegative(num2)) {
            return subtractPositive(num2[1..num2.size], num1[1..num1.size])
        } else if (isNegative(num1)) {
            let sum = addPositive(num1[1..num1.size], num2)
            return "-" + sum
        } else {
            return addPositive(num1, num2[1..num2.size])
        }
    }

    private static func subtractPositive(a: String, b: String): String {
        // Determine sign by comparing absolute values
        let cmp = absCompare(a, b)
        let (sign, large, small) = if (cmp >= 0) {
            ("", a, b)
        } else {
            ("-", b, a)
        }

        let i = large.size - 1
        let j = small.size - 1
        let borrow = 0
        let result = ArrayList<UInt8>()

        var ii = i
        var jj = j
        var bb = borrow

        while (ii >= 0) {
            let x = large[ii] - '0'
            let y = if (jj >= 0) { small[jj] - '0' } else { 0 }
            let diff = x - y - bb
            if (diff < 0) {
                bb = 1
                result.add(diff + 10, at: 0)
            } else {
                bb = 0
                result.add(diff, at: 0)
            }
            ii = ii - 1
            jj = jj - 1
        }

        let sb = ArrayList<String>()
        for (digit in result) {
            sb.add(String(digit))
        }
        let raw = sb.join("")
        let cleaned = removeLeadingZeros(raw)
        return if (sign == "" || cleaned == "0") { cleaned } else { sign + cleaned }
    }

    public static func multiply(num1: String, num2: String): String {
        // Handle zero
        if (num1 == "0" || num2 == "0") {
            return "0"
        }

        // Handle signs
        let neg1 = isNegative(num1)
        let neg2 = isNegative(num2)
        let a = if (neg1) { num1[1..num1.size] } else { num1 }
        let b = if (neg2) { num2[1..num2.size] } else { num2 }
        let negativeResult = neg1 != neg2

        let m = a.size
        let n = b.size
        let pos = m + n
        let result = Array<UInt8>(pos, filling: 0)

        var i = m - 1
        while (i >= 0) {
            var j = n - 1
            while (j >= 0) {
                let mul = (a[i] - '0') * (b[j] - '0')
                let p1 = i + j
                let p2 = i + j + 1
                let sum = mul + result[p2]
                result[p2] = sum % 10
                result[p1] = result[p1] + sum / 10
                j = j - 1
            }
            i = i - 1
        }

        // Convert result to string
        let sb = ArrayList<String>()
        var started = false
        for (digit in result) {
            if (digit != 0) {
                started = true
            }
            if (started) {
                sb.add(String(digit))
            }
        }
        let resStr = sb.join("")
        return if (negativeResult && resStr != "0") { "-" + resStr } else { resStr }
    }
}

