        let aClean = if (isNegative(a)) { a[1..a.size] } else { a }
        let bClean = if (isNegative(b)) { b[1..b.size] } else { b }

        if (aClean.size < bClean.size) { return -1 }
        if (aClean.size > bClean.size) { return 1 }

        for (i in 0..aClean.size) {
            if (aClean[i] < bClean[i]) { return -1 }
            if (aClean[i] > bClean[i]) { return 1 }
        }
        return 0
    }

    // Helper: add two positive number strings
    private static func absAdd(a: String, b: String): String {
        let aClean = if (isNegative(a)) { a[1..a.size] } else { a }
        let bClean = if (isNegative(b)) { b[1..b.size] } else { b }

        let i = aClean.size - 1
        let j = bClean.size - 1
        let result = ArrayList<Char>()
        let carry = 0

        while (i >= 0 || j >= 0 || carry > 0) {
            let digitA = if (i >= 0) { aClean[i] as Int64 - '0' as Int64 } else { 0 }
            let digitB = if (j >= 0) { bClean[j] as Int64 - '0' as Int64 } else { 0 }
            let total = digitA + digitB + carry
            result.add((total % 10) + '0' as Char, at: 0)
            carry = total / 10
            i = i - 1
            j = j - 1
        }

        return result.join("")
    }

    // Helper: subtract two positive number strings (a - b), assumes |a| >= |b|
    private static func absSubtract(larger: String, smaller: String): String {
        let aClean = if (isNegative(larger)) { larger[1..larger.size] } else { larger }
        let bClean = if (isNegative(smaller)) { smaller[1..smaller.size] } else { smaller }

        let i = aClean.size - 1
        let j = bClean.size - 1
        let result = ArrayList<Char>()
        let borrow = 0

        var tempA = ArrayList<Char>()
        for (c in aClean.runes()) { tempA.add(c as Char) }

        while (i >= 0) {
            let mut digitA = tempA[i] as Int64 - '0' as Int64
            let digitB = if (j >= 0) { bClean[j] as Int64 - '0' as Int64 } else { 0 }

            if (digitA < digitB) {
                digitA = digitA + 10
                // Simulate borrow from next digit
                var k = i - 1
                while (k >= 0 && tempA[k] == '0') {
                    tempA[k] = '9'
                    k = k - 1
                }
                if (k >= 0) {
                    tempA[k] = (tempA[k] as Int64 - '0' as Int64 - 1 + '0' as Int64) as Char
                }
            }

            let digit = digitA - digitB
            result.add((digit + '0' as Int64) as Char, at: 0)
            i = i - 1
            j = j - 1
        }

        // Remove leading zeros
        let resStr = result.join("")
        let trimmed = resStr.trimStart("0")
        return if (trimmed == "") { "0" } else { trimmed }
    }

    public static func add(num1: String, num2: String): String {
        if (isNegative(num1) && isNegative(num2)) {
            return '-' + absAdd(num1, num2)
        } else if (isNegative(num1)) {
            return subtract(num2, num1[1..num1.size])
        } else if (isNegative(num2)) {
            return subtract(num1, num2[1..num2.size])
        } else {
            return absAdd(num1, num2)
        }
    }

    public static func subtract(num1: String, num2: String): String {
        if (!isNegative(num1) && isNegative(num2)) {
            return add(num1, num2[1..num2.size])
        } else if (isNegative(num1) && !isNegative(num2)) {
            return '-' + add(num1[1..num1.size], num2)
        } else if (isNegative(num1) && isNegative(num2)) {
            return subtract(num2[1..num2.size], num1[1..num1.size])
        } else {
            // Both positive
            let cmp = absCompare(num1, num2)
            if (cmp == 0) { return "0" }
            if (cmp > 0) {
                return absSubtract(num1, num2)
            } else {
                return '-' + absSubtract(num2, num1)
            }
        }
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") { return "0" }

        let neg1 = isNegative(num1)
        let neg2 = isNegative(num2)
        let a = if (neg1) { num1[1..num1.size] } else { num1 }
        let b = if (neg2) { num2[1..num2.size] } else { num2 }

        let m = a.size
        let n = b.size
        let result = Array<Int64>(Array.fill(0, size: m + n))

        // Multiply digit by digit
        for (i in 0..m) {
            for (j in 0..n) {
                let mul = (a[m - 1 - i] as Int64 - '0' as Int64) * (b[n - 1 - j] as Int64 - '0' as Int64)
                let p1 = i + j
                let p2 = i + j + 1
                let sum = mul + result[p2]

                result[p2] = sum % 10
                result[p1] += sum / 10
            }
        }

        // Convert result to string
        let sb = ArrayList<Char>()
        for (digit in result) {
            if (sb.size > 0 || digit != 0) { // avoid leading zeros
                sb.add((digit + '0' as Int64) as Char)
            }
        }

        let resStr = sb.join("")
        if (resStr == "") { return "0" }

        return if (neg1 != neg2) { '-' + resStr } else { resStr }
    }
}

import std.collection.*
