class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    private static func reverseStr(s: String): String {
        let runes = s.toRuneArray()
        var reversed = ArrayList<Rune>()
        for (i in (runes.size - 1)..-1:-1) {
            reversed.add(runes[i])
        }
        let sb = StringBuilder()
        for (r in reversed) {
            sb.append(r)
        }
        return sb.toString()
    }

    private static func isNegative(s: String): Bool {
        return s[0] == r'-'
    }

    private static func stripSign(s: String): String {
        return if (isNegative(s)) { s[1..] } else { s }
    }

    private static func compareAbs(num1: String, num2: String): Int64 {
        let a = stripSign(num1)
        let b = stripSign(num2)
        if (a.size < b.size) { return -1 }
        if (a.size > b.size) { return 1 }
        for (i in 0..a.size) {
            if (a[i] < b[i]) { return -1 }
            if (a[i] > b[i]) { return 1 }
        }
        return 0
    }

    public static func add(num1: String, num2: String): String {
        if (isNegative(num1) && !isNegative(num2)) {
            return subtract(num2, stripSign(num1))
        }
        if (!isNegative(num1) && isNegative(num2)) {
            return subtract(num1, stripSign(num2))
        }
        if (isNegative(num1) && isNegative(num2)) {
            return "-" + add(stripSign(num1), stripSign(num2))
        }

        let a = reverseStr(num1)
        let b = reverseStr(num2)
        var result = StringBuilder()
        var carry = 0
        let maxLen = if (a.size > b.size) { a.size } else { b.size }

        for (i in 0..maxLen) {
            let digitA = if (i < a.size) { a[i].toInt() - r'0'.toInt() } else { 0 }
            let digitB = if (i < b.size) { b[i].toInt() - r'0'.toInt() } else { 0 }
            let total = digitA + digitB + carry
            result.append(r'0' + (total % 10))
            carry = total / 10
        }

        if (carry > 0) {
            result.append(r'0' + carry)
        }

        let resStr = reverseStr(result.toString())
        // Remove leading zeros
        var idx = 0
        while (idx < resStr.size - 1 && resStr[idx] == r'0') {
            idx = idx + 1
        }
        return resStr[idx..]
    }

    public static func subtract(num1: String, num2: String): String {
        if (isNegative(num1) && !isNegative(num2)) {
            return "-" + add(stripSign(num1), num2)
        }
        if (!isNegative(num1) && isNegative(num2)) {
            return add(num1, stripSign(num2))
        }
        if (isNegative(num1) && isNegative(num2)) {
            return subtract(stripSign(num2), stripSign(num1))
        }

        let cmp = compareAbs(num1, num2)
        if (cmp == 0) { return "0" }
        if (cmp < 0) {
            return "-" + subtract(num2, num1)
        }

        let a = reverseStr(num1)
        let b = reverseStr(num2)
        var result = StringBuilder()
        var borrow = 0

        for (i in 0..a.size) {
            let digitA = a[i].toInt() - r'0'.toInt() - borrow
            let digitB = if (i < b.size) { b[i].toInt() - r'0'.toInt() } else { 0 }
            var digit = digitA - digitB
            borrow = 0
            if (digit < 0) {
                digit = digit + 10
                borrow = 1
            }
            result.append(r'0' + digit)
        }

        let resStr = reverseStr(result.toString())
        var idx = 0
        while (idx < resStr.size - 1 && resStr[idx] == r'0') {
            idx = idx + 1
        }
        return resStr[idx..]
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") { return "0" }

        let isNeg = if (isNegative(num1) != isNegative(num2)) { true } else { false }
        let a = stripSign(num1)
        let b = stripSign(num2)

        let m = a.size
        let n = b.size
        var result = Array<UInt8>(repeat: 0, count: m + n)

        for (i in (m - 1)..-1:-1) {
            for (j in (n - 1)..-1:-1) {
                let mul = (a[i].toInt() - r'0'.toInt()) * (b[j].toInt() - r'0'.toInt())
                let p1 = i + j
                let p2 = i + j + 1
                let sum = mul + result[p2]
                result[p2] = sum % 10
                result[p1] = result[p1] + sum / 10
            }
        }

        var sb = StringBuilder()
        for (digit in result) {
            if (!(sb.size == 0 && digit == 0)) {
                sb.append(r'0' + digit)
            }
        }

        let resStr = sb.toString()
        return if (resStr == "") { "0" } else { if (isNeg) { "-" + resStr } else { resStr } }
    }
}

