class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    // Helper: check if a number is negative
    private static func isNegative(num: String): Bool {
        return num[0] == '-'
    }

    // Helper: compare absolute values of two positive number strings
    private static func absCompare(num1: String, num2: String): Int64 {
        let len1 = num1.size
        let len2 = num2.size
        if (len1 < len2) { return -1 }
        if (len1 > len2) { return 1 }
        for (i in 0..len1) {
            if (num1[i] < num2[i]) { return -1 }
            if (num1[i] > num2[i]) { return 1 }
        }
        return 0
    }

    // Helper: strip sign
    private static func stripSign(num: String): String {
        return if (isNegative(num)) { num[1..num.size] } else { num }
    }

    // Helper: remove leading zeros
    private static func removeLeadingZeros(s: String): String {
        var i = 0
        while (i < s.size && s[i] == '0') { i = i + 1 }
        return if (i == s.size) { "0" } else { s[i..s.size] }
    }

    public static func add(num1: String, num2: String): String {
        // Handle negative numbers
        if (isNegative(num1) && isNegative(num2)) {
            return "-" + add(stripSign(num1), stripSign(num2))
        } else if (isNegative(num1)) {
            return subtract(num2, stripSign(num1))
        } else if (isNegative(num2)) {
            return subtract(num1, stripSign(num2))
        }

        // Both are positive
        let len1 = num1.size
        let len2 = num2.size
        let maxLen = if (len1 > len2) { len1 } else { len2 }
        var result = ArrayList<Rune>()
        var carry = 0
        var i = len1 - 1
        var j = len2 - 1

        while (i >= 0 || j >= 0 || carry > 0) {
            let digit1 = if (i >= 0) { num1[i] as Int64 - '0' as Int64 } else { 0 }
            let digit2 = if (j >= 0) { num2[j] as Int64 - '0' as Int64 } else { 0 }
            let sum = digit1 + digit2 + carry
            result.add(((sum % 10) + '0' as Int64) as Rune, at: 0)
            carry = sum / 10
            i = i - 1
            j = j - 1
        }

        let resultStr = String(result)
        return removeLeadingZeros(resultStr)
    }

    public static func subtract(num1: String, num2: String): String {
        // Handle negative cases
        if (isNegative(num1) && isNegative(num2)) {
            return subtract(stripSign(num2), stripSign(num1))
        } else if (isNegative(num1)) {
            return "-" + add(stripSign(num1), num2)
        } else if (isNegative(num2)) {
            return add(num1, stripSign(num2))
        }

        // Both are positive
        let a = stripSign(num1)
        let b = stripSign(num2)
        let cmp = absCompare(a, b)

        if (cmp == 0) { return "0" }
        if (cmp < 0) {
            return "-" + subtract(b, a)
        }

        // a > b
        var result = ArrayList<Rune>()
        var borrow = 0
        var i = a.size - 1
        var j = b.size - 1

        while (i >= 0) {
            let digit1 = (a[i] as Int64 - '0' as Int64) - borrow
            let digit2 = if (j >= 0) { b[j] as Int64 - '0' as Int64 } else { 0 }
            var digit = digit1 - digit2
            borrow = 0
            if (digit < 0) {
                digit = digit + 10
                borrow = 1
            }
            result.add((digit + '0' as Int64) as Rune, at: 0)
            i = i - 1
            j = j - 1
        }

        let resultStr = String(result)
        return removeLeadingZeros(resultStr)
    }

    public static func multiply(num1: String, num2: String): String {
        // Handle signs
        let negative = isNegative(num1) ^ isNegative(num2)
        let a = stripSign(num1)
        let b = stripSign(num2)

        let len1 = a.size
        let len2 = b.size
        var result = Array<Int64>(len1 + len2, init: 0)

        for (i in 0..len1) {
            for (j in 0..len2) {
                let mul = (a[len1 - 1 - i] as Int64 - '0' as Int64) *
                          (b[len2 - 1 - j] as Int64 - '0' as Int64)
                let sum = mul + result[i + j]
                result[i + j] = sum % 10
                result[i + j + 1] = result[i + j + 1] + sum / 10
            }
        }

        // Convert result to string
        var str = ArrayList<Rune>()
        var leading = true
        for (i in (result.size - 1)..0:-1) {
            if (leading && result[i] == 0) { continue }
            leading = false
            str.add((result[i] + '0' as Int64) as Rune)
        }

        let resultStr = if (str.size == 0) { "0" } else { String(str) }
        let final = removeLeadingZeros(resultStr)
        return if (negative && final != "0") { "-" + final } else { final }
    }
}

