        while (i >= 0) {
            var diff = (num1[i] - '0') - borrow
            if (j >= 0) { diff -= (num2[j] - '0') }
            if (diff < 0) {
                diff += 10
                borrow = 1
            } else {
                borrow = 0
            }
            res.add(((diff + '0')), at: 0)
            i -= 1
            j -= 1
        }
        // Remove leading zeros
        let s = String(res)
        var k = 0
        while (k < s.size - 1 && s[k] == '0') { k += 1 }
        return s.substring(k)
    }

    public static func add(num1: String, num2: String): String {
        if (isNegative(num1) && isNegative(num2)) {
            return '-' + absAdd(stripSign(num1), stripSign(num2))
        } else if (isNegative(num1)) {
            return subtract(num2, stripSign(num1))
        } else if (isNegative(num2)) {
            return subtract(num1, stripSign(num2))
        } else {
            return absAdd(num1, num2)
        }
    }

    public static func subtract(num1: String, num2: String): String {
        if (isNegative(num1) && isNegative(num2)) {
            // (-a) - (-b) = b - a
            return subtract(stripSign(num2), stripSign(num1))
        } else if (isNegative(num1)) {
            // (-a) - b = -(a + b)
            return '-' + absAdd(stripSign(num1), num2)
        } else if (isNegative(num2)) {
            // a - (-b) = a + b
            return absAdd(num1, stripSign(num2))
        } else {
            // a - b
            let cmp = absCompare(num1, num2)
            if (cmp == 0) { return "0" }
            if (cmp > 0) {
                return absSubtract(num1, num2)
            } else {
                return '-' + absSubtract(num2, num1)
            }
        }
    }

    public static func multiply(num1: String, num2: String): String {
        // Handle signs
        let negative = isNegative(num1) != isNegative(num2)
        let a = stripSign(num1)
        let b = stripSign(num2)

        let m = a.size
        let n = b.size
        let result = Array<Int64>(m + n, fill: 0)

        // Multiply digit by digit
        for (i in 0..m) {
            for (j in 0..n) {
                let mul = (a[m - 1 - i] - '0') * (b[n - 1 - j] - '0')
                let sum = mul + result[i + j]
                result[i + j] = sum % 10
                result[i + j + 1] += sum / 10
            }
        }

        // Build result string from digits
        let sb = ArrayList<Char>()
        var started = false
        for (k in 0..result.size) {
            let i = result.size - 1 - k
            if (result[i] != 0) { started = true }
            if (started) { sb.add((result[i] + '0')) }
        }

        let resStr = if (sb.size == 0) { "0" } else { String(sb) }
        return if (negative && resStr != "0") { '-' + resStr } else { resStr }
    }
}

