class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    // Helper: check if a string represents a negative number
    private static func isNegative(s: String): Bool {
        return s[0] == '-'
    }

    // Helper: remove sign for processing
    private static func stripSign(s: String): String {
        return if (isNegative(s)) { s.substring(1) } else { s }
    }

    // Helper: compare absolute values of two positive number strings
    private static func absCompare(a: String, b: String): Int64 {
        let a_len = a.size
        let b_len = b.size
        if (a_len < b_len) { return -1 }
        if (a_len > b_len) { return 1 }
        for (i in 0..a_len) {
            if (a[i] < b[i]) { return -1 }
            if (a[i] > b[i]) { return 1 }
        }
        return 0
    }

    // Helper: add two positive number strings
    private static func addPositive(a: String, b: String): String {
        let i = a.size - 1
        let j = b.size - 1
        let result = ArrayList<Char>()
        var carry = 0
        while (i >= 0 || j >= 0 || carry != 0) {
            let x = if (i >= 0) { a[i] as Int64 - '0' as Int64 } else { 0 }
            let y = if (j >= 0) { b[j] as Int64 - '0' as Int64 } else { 0 }
            let total = x + y + carry
            result.add((total % 10 as Int64 + '0' as Int64) as Char, at: 0)
            carry = total / 10 as Int64
            i = i - 1
            j = j - 1
        }
        return result.toArray().join("")
    }

    // Helper: subtract two positive number strings (a >= b assumed)
    private static func subtractPositive(a: String, b: String): String {
        let i = a.size - 1
        let j = b.size - 1
        let result = ArrayList<Char>()
        var borrow = 0
        while (i >= 0 || j >= 0) {
            let x = if (i >= 0) { a[i] as Int64 - '0' as Int64 } else { 0 }
            let y = if (j >= 0) { b[j] as Int64 - '0' as Int64 } else { 0 }
            let mut digit = x - y - borrow
            if (digit < 0) {
                digit = digit + 10
                borrow = 1
            } else {
                borrow = 0
            }
            result.add((digit + '0' as Int64) as Char, at: 0)
            i = i - 1
            j = j - 1
        }
        // Remove leading zeros
        let res_str = result.toArray().join("")
        let trimmed = res_str.lstrip('0')
        return if (trimmed == "") { "0" } else { trimmed }
    }

    public static func add(num1: String, num2: String): String {
        /*
        Adds two big numbers.
        :param num1: The first number to add, String.
        :param num2: The second number to add, String.
        :return: The sum of the two numbers, String.
        */
        let neg1 = isNegative(num1)
        let neg2 = isNegative(num2)
        let a = stripSign(num1)
        let b = stripSign(num2)

        if (!neg1 && !neg2) {
            return addPositive(a, b)
        } else if (neg1 && neg2) {
            return "-" + addPositive(a, b)
        } else if (neg1) {
            // -a + b = b - a
            let cmp = absCompare(b, a)
            if (cmp == 0) { return "0" }
            if (cmp > 0) {
                return subtractPositive(b, a)
            } else {
                return "-" + subtractPositive(a, b)
            }
        } else {
            // a - b
            let cmp = absCompare(a, b)
            if (cmp == 0) { return "0" }
            if (cmp > 0) {
                return subtractPositive(a, b)
            } else {
                return "-" + subtractPositive(b, a)
            }
        }
    }

    public static func subtract(num1: String, num2: String): String {
        /*
        Subtracts two big numbers.
        :param num1: The first number to subtract, String.
        :param num2: The second number to subtract, String.
        :return: The difference of the two numbers, String.
        */
        let neg1 = isNegative(num1)
        let neg2 = isNegative(num2)
        let a = stripSign(num1)
        let b = stripSign(num2)

        if (!neg1 && !neg2) {
            let cmp = absCompare(a, b)
            if (cmp == 0) { return "0" }
            if (cmp > 0) {
                return subtractPositive(a, b)
            } else {
                return "-" + subtractPositive(b, a)
            }
        } else if (neg1 && neg2) {
            // -a - (-b) = b - a
            let cmp = absCompare(b, a)
            if (cmp == 0) { return "0" }
            if (cmp > 0) {
                return subtractPositive(b, a)
            } else {
                return "-" + subtractPositive(a, b)
            }
        } else if (!neg1 && neg2) {
            // a - (-b) = a + b
            return addPositive(a, b)
        } else {
            // -a - b = -(a + b)
            return "-" + addPositive(a, b)
        }
    }

    public static func multiply(num1: String, num2: String): String {
        /*
        Multiplies two big numbers.
        :param num1: The first number to multiply, String.
        :param num2: The second number to multiply, String.
        :return: The product of the two numbers, String.
        */
        let neg1 = isNegative(num1)
        let neg2 = isNegative(num2)
        let a = stripSign(num1)
        let b = stripSign(num2)

        if (a == "0" || b == "0") { return "0" }

        let len1 = a.size
        let len2 = b.size
        let result = Array<Int64>(0, len1 + len2)

        // Multiply digit by digit
        for (i in 0..len1) {
            for (j in 0..len2) {
                let mul = (a[len1 - 1 - i] as Int64 - '0' as Int64) * (b[len2 - 1 - j] as Int64 - '0' as Int64)
                let sum = mul + result[i + j]
                result[i + j] = sum % 10
                result[i + j + 1] = result[i + j + 1] + sum / 10
            }
        }

        // Convert result to string
        let sb = ArrayList<Char>()
        var started = false
        for (i in (len1 + len2 - 1)..(-1): -1) {
            if (result[i] != 0) { started = true }
            if (started) {
                sb.add((result[i] + '0' as Int64) as Char)
            }
        }

        let res_str = sb.toArray().join("")
        let sign = if (neg1 ^ neg2) { "-" } else { "" }
        return sign + res_str
    }
}

