class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    // Helper: check if a number is negative
    private static func isNegative(num: String): Bool {
        return num[0] == '-'
    }

    // Helper: compare absolute values of two positive number strings
    private static func absCompare(num1: String, num2: String): Int64 {
        let len1 = num1.size
        let len2 = num2.size
        if (len1 < len2) {
            return -1
        } else if (len1 > len2) {
            return 1
        } else {
            for (i in 0..len1) {
                if (num1[i] < num2[i]) {
                    return -1
                } else if (num1[i] > num2[i]) {
                    return 1
                }
            }
            return 0
        }
    }

    // Helper: remove leading zeros
    private static func removeLeadingZeros(s: String): String {
        var i = 0
        while (i < s.size && s[i] == '0') {
            i = i + 1
        }
        if (i == s.size) {
            return "0"
        }
        return s.substring(i)
    }

    public static func add(num1: String, num2: String): String {
        // Handle signs
        if (!isNegative(num1) && !isNegative(num2)) {
            return addAbs(num1, num2)
        } else if (isNegative(num1) && isNegative(num2)) {
            let result = addAbs(num1.substring(1), num2.substring(1))
            return "-" + result
        } else if (isNegative(num1)) {
            return subtractAbs(num2, num1.substring(1))
        } else {
            return subtractAbs(num1, num2.substring(1))
        }
    }

    public static func subtract(num1: String, num2: String): String {
        if (!isNegative(num1) && !isNegative(num2)) {
            return subtractAbs(num1, num2)
        } else if (isNegative(num1) && isNegative(num2)) {
            return subtractAbs(num2.substring(1), num1.substring(1))
        } else if (isNegative(num1)) {
            let result = addAbs(num1.substring(1), num2)
            return "-" + result
        } else {
            return addAbs(num1, num2.substring(1))
        }
    }

    // Add two positive integers as strings
    private static func addAbs(n1: String, n2: String): String {
        var result = ""
        var i = n1.size - 1
        var j = n2.size - 1
        var carry = 0

        while (i >= 0 || j >= 0 || carry > 0) {
            let val1 = if (i >= 0) { n1[i].toInt() - '0'.toInt() } else { 0 }
            let val2 = if (j >= 0) { n2[j].toInt() - '0'.toInt() } else { 0 }
            let total = val1 + val2 + carry
            result = String(total % 10) + result
            carry = total / 10
            i = i - 1
            j = j - 1
        }

        return removeLeadingZeros(result)
    }

    // Subtract two positive integers (n1 - n2), return signed result
    private static func subtractAbs(n1: String, n2: String): String {
        let cmp = absCompare(n1, n2)
        if (cmp == 0) {
            return "0"
        } else if (cmp > 0) {
            var result = ""
            var i = n1.size - 1
            var j = n2.size - 1
            var borrow = 0

            while (i >= 0) {
                let val1 = n1[i].toInt() - '0'.toInt() - borrow
                let val2 = if (j >= 0) { n2[j].toInt() - '0'.toInt() } else { 0 }
                borrow = if (val1 < val2) { 1 } else { 0 }
                let digit = if (val1 < val2) { val1 + 10 - val2 } else { val1 - val2 }
                result = String(digit) + result
                i = i - 1
                j = j - 1
            }
            return removeLeadingZeros(result)
        } else {
            var result = subtractAbs(n2, n1)
            if (result != "0") {
                result = "-" + result
            }
            return result
        }
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") {
            return "0"
        }

        let sign = if (isNegative(num1) != isNegative(num2)) { -1 } else { 1 }
        let n1 = if (isNegative(num1)) { num1.substring(1) } else { num1 }
        let n2 = if (isNegative(num2)) { num2.substring(1) } else { num2 }

        let len1 = n1.size
        let len2 = n2.size
        var result = Array<Int64>(fill: 0, size: len1 + len2)

        for (i in len1 - 1..-1:-1) {
            for (j in len2 - 1..-1:-1) {
                let mul = (n1[i].toInt() - '0'.toInt()) * (n2[j].toInt() - '0'.toInt())
                let p1 = i + j
                let p2 = i + j + 1
                let sum = mul + result[p2]

                result[p2] = sum % 10
                result[p1] = result[p1] + (sum / 10)
            }
        }

        var resultStr = ""
        for (digit in result) {
            resultStr = resultStr + String(digit)
        }

        resultStr = removeLeadingZeros(resultStr)

        if (sign == -1 && resultStr != "0") {
            resultStr = "-" + resultStr
        }

        return resultStr
    }
}

import std.collection.*
import std.convert.RadixConvertible

class BinaryDataProcessor {

    /*
    This is a class used to process binary data, which includes functions such as clearing non 0 or 1 characters, counting binary string information, and converting to corresponding strings based on different encoding methods.
    */

    var binary_string: String

    public init(binary_string: String) {
        /*
        Initialize the class with a binary string and clean it by removing all non 0 or 1 characters.
        */
        this.binary_string = binary_string
        this.clean_non_binary_chars()
    }

    public func clean_non_binary_chars(): Unit {
        /*
        Clean the binary string by removing all non 0 or 1 characters.
        >>> bdp = BinaryDataProcessor("01101000daf3e4r01100101011011000110110001101111")
        >>> bdp.clean_non_binary_chars()
        >>> bdp.binary_string
        '0110100001100101011011000110110001101111'
        */
        let cleaned = StringBuilder()
        for (r in this.binary_string.runes()) {
            if (r == r'0' || r == r'1') {
                cleaned.append(r)
            }
        }
        this.binary_string = cleaned.toString()
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        /*
        Calculate the binary string information, including the percentage of 0 and 1, and the total length of the binary string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.calculate_binary_info()
        {'Zeroes': 0.475, 'Ones': 0.525, 'Bit length': 40.0}
        */
        let len = this.binary_string.size
        if (len == 0) {
            let result = HashMap<String, Float64>()
            result.add("Zeroes", 0.0)
            result.add("Ones", 0.0)
            result.add("Bit length", 0.0)
            return result
        }

        var count_0 = 0
        for (r in this.binary_string.runes()) {
            if (r == r'0') {
                count_0 += 1
            }
        }
        let count_1 = len - count_0

        let result = HashMap<String, Float64>()
        result.add("Zeroes", count_0 as Float64 / len as Float64)
        result.add("Ones", count_1 as Float64 / len as Float64)
        result.add("Bit length", len as Float64)
        return result
    }

    public func convert_to_ascii(): String {
        /*
        Convert the binary string to ascii string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.convert_to_ascii()
        'hello'
        */
        return this.binary_to_string(8)
    }

    public func convert_to_utf8(): String {
        /*
        Convert the binary string to utf-8 string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.convert_to_utf8()
        'hello'
        */
        return this.binary_to_string(8) // For this case, one byte per char
    }

    private func binary_to_string(chunk_size: Int64): String {
        let result = StringBuilder()
        let bits = this.binary_string
        let n = bits.size

        for (i in 0..n:chunk_size) {
            if (i + chunk_size > n) break
            let chunk = bits[i:i+chunk_size]
            let value = Int64(chunk, radix: 2) ?? 0
            result.append(value.toRune())
        }

        return result.toString()
    }
}

