        this.clean_non_binary_chars()
    }

    public func clean_non_binary_chars(): Unit {
        let mut cleaned = ""
        for (r in binary_string.runes()) {
            if (r == r'0' || r == r'1') {
                cleaned = cleaned + r.toStr()
            }
        }
        this.binary_string = cleaned
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        let total = binary_string.size
        if (total == 0) {
            let result = HashMap<String, Float64>([])
            result.add("Zeroes", 0.0)
            result.add("Ones", 0.0)
            result.add("Bit length", 0.0)
            return result
        }

        var zero_count = 0
        for (r in binary_string.runes()) {
            if (r == r'0') {
                zero_count = zero_count + 1
            }
        }
        let one_count = total - zero_count

        let result = HashMap<String, Float64>([])
        result.add("Zeroes", zero_count as Float64 / total)
        result.add("Ones", one_count as Float64 / total)
        result.add("Bit length", total as Float64)
        return result
    }

    public func convert_to_ascii(): String {
        let mut result = ""
        let mut i = 0
        let data = binary_string

        while (i < data.size) {
            let remaining = data.size - i
            if (remaining < 8) {
                break
            }
            let chunk = data.substring(i, i + 8)
            let byte_val = RadixConvertible.parseInt(chunk, radix: 2) ?? 0
            result = result + String.fromByte(byte_val as UInt8)
            i = i + 8
        }
        return result
    }

    public func convert_to_utf8(): String {
        // In this case, since input is clean 8-bit binary and represents ASCII,
        // ASCII is a subset of UTF-8, so direct byte-to-codepoint mapping works.
        return this.convert_to_ascii()
    }
}

