        var aces: Int64 = 0
        for (card in hand) {
            let rank = card[0..]  // first character(s); may be A,2-9,1, J, Q, K
            // Handle '10' as special case since it has two characters
            if (card.size >= 2 && card[0..2] == "10") {
                value += 10
            } else {
                match (rank[0]) {
                    case 'A' => {
                        value += 11
                        aces += 1
                    }
                    case 'J' | 'Q' | 'K' => {
                        value += 10
                    }
                    case _ => {
