        >>> boyerMooreSearch.match_in_pattern("A")
        0

        */
        // Since `char` is a String, we take its first character
        let c: Rune = char.runes().next() ?? return -1
        // Traverse pattern from right to left to find rightmost occurrence
        for (i in patLen - 1..-1:-1) {
            if (pattern[i] == c) {
                return i
            }
        }
        return -1
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        /*
        Determines the position of the first mismatch between the pattern and the text.
