        var shift: Int64 = 0

        // Preprocess: Build bad character shift table
        let badCharShift = HashMap<Rune, Int64>()
        let patRunes = pattern.toRuneArray()
        for (i in 0..patLen) {
            badCharShift.add(patRunes[i], i)
        }

        while (shift <= textLen - patLen) {
            var j: Int64 = patLen - 1
            while (j >= 0 && pattern[j] == text[shift + j]) {
                j = j - 1
            }
