                let mismatchedChar: Rune = text[shift + j]
                let index: Int64 = badCharShift.get(mismatchedChar) ?? -1
                let bcShift: Int64 = j - index
                shift = shift + (if (bcShift > 0) { bcShift } else { 1 })
            }
        }
        return result
    }
