class ClassRegistrationSystem {

    var students: ArrayList<HashMap<String, String>>
    var students_registration_classes: HashMap<String, ArrayList<String>>

    public init() {
        this.students = ArrayList<HashMap<String, String>>()
        this.students_registration_classes = HashMap<String, ArrayList<String>>()
    }

    public func register_student(student: HashMap<String, String>): Int64 {
        let name = student["name"] ?? ""
        let major = student["major"] ?? ""
        if (name == "" || major == "") {
            return 0
        }
        for (s in 0..this.students.size) {
            let existing_student = this.students[s]
            if (existing_student["name"] == name) {
                return 0
            }
        }
        this.students.add(student)
        if (!this.students_registration_classes.contains(name)) {
            this.students_registration_classes.add(name, ArrayList<String>())
        }
        return 1
    }

    public func register_class(student_name: String, class_name: String): ArrayList<String> {
        if (!this.students_registration_classes.contains(student_name)) {
            this.students_registration_classes.add(student_name, ArrayList<String>())
        }
        let class_list = this.students_registration_classes[student_name]
        for (i in 0..class_list.size) {
            if (class_list[i] == class_name) {
                return class_list
            }
        }
        class_list.add(class_name, at: class_list.size)
        return class_list
    }

    public func get_students_by_major(major: String): ArrayList<String> {
        let result = ArrayList<String>()
        for (i in 0..this.students.size) {
            let student = this.students[i]
            let student_major = student["major"] ?? ""
            let student_name = student["name"] ?? ""
            if (student_major == major) {
                result.add(student_name, at: result.size)
            }
        }
        return result
    }

    public func get_all_major(): ArrayList<String> {
        let majors = HashSet<String>()
        for (i in 0..this.students.size) {
            let major = this.students[i]["major"] ?? ""
            if (major != "") {
                majors.add(major)
            }
        }
        let result = ArrayList<String>()
        for (major in majors) {
            result.add(major, at: result.size)
        }
        return result
    }

    public func get_most_popular_class_in_major(major: String): String {
        let relevant_students = this.get_students_by_major(major)
        if (relevant_students.size == 0) {
            return ""
        }
        let class_count = HashMap<String, Int64>()
        for (i in 0..relevant_students.size) {
            let name = relevant_students[i]
            if (this.students_registration_classes.contains(name)) {
                let classes = this.students_registration_classes[name]
                for (j in 0..classes.size) {
                    let class_name = classes[j]
                    let count = class_count.get(class_name) ?? 0
                    class_count.add(class_name, count + 1)
                }
            }
        }
        var max_count = 0
        var most_popular = ""
        for (entry in class_count) {
            let class_name = entry.key()
            let count = entry.value()
            if (count > max_count) {
                max_count = count
                most_popular = class_name
            }
        }
        return most_popular
    }
}

