import std.collection.*
import std.fs.*
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file = File.open(file_name, mode: "r")
        if (file == None<File>) {
            return (ArrayList<String>(), ArrayList<ArrayList<String>>())
        }
        let content = file.getOrThrow().readAll()
        file.getOrThrow().close()

        let lines = content.split("\n")
        let title_line = lines[0]
        let title = ArrayList<String>(title_line.split(","))
        let data = ArrayList<ArrayList<String>>()

        for (i in 1..lines.size) {
            if (lines[i].trim().size == 0) {
                continue
            }
            let row = ArrayList<String>(lines[i].split(","))
            data.add(row)
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let file = File.open(file_name, mode: "w")
        if (file == None<File>) {
            return 0
        }
        let writer = file.getOrThrow()

        for (i in 0..data.size) {
            let line_parts = ArrayList<String>()
            let row = data[i]
            for (j in 0..row.size) {
                line_parts.add(row[j])
            }
            let line = line_parts.join(",")
            writer.write(line)
            if (i < data.size - 1) {
                writer.write("\n")
            }
        }

        writer.close()
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = read_csv(save_file_name)
        if (data.size == 0 && title.size == 0) {
            return 0
        }

        let new_data = ArrayList<ArrayList<String>>()
        for (i in 0..data.size) {
            if (N >= data[i].size || N < 0) {
                continue
            }
            let cell = data[i][N].trim()
            let upper_cell = cell.upper()
            let new_row = ArrayList<String>()
            new_row.add(upper_cell)
            new_data.add(new_row)
        }

        let base_name = save_file_name.split(".")[0]
        let ext = if (save_file_name.contains(".")) { save_file_name.split(".").runes().last().toString() } else { "" }
        let output_file = if (ext != "") { "${base_name}_process.${ext}" } else { "${base_name}_process" }

        let output_data = ArrayList<ArrayList<String>>()
        output_data.add(title)
        for (row in new_data) {
            output_data.add(row)
        }

        return write_csv(output_data, output_file)
    }
}

import std.collection.ArrayList
import std.fs.*
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    /*
    This is a class for processing CSV files, including reading and writing CSV data, as well as processing specific operations and saving as a new CSV file.
    */

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file = File.open(file_name, mode: "r")
        if (file == None<File>) {
            return (ArrayList<String>(), ArrayList<ArrayList<String>>())
        }
        let content = file.getOrThrow().readAll()
        file.getOrThrow().close()

        let lines = content.split("\n")
        let title = ArrayList<String>()
        let data = ArrayList<ArrayList<String>>()

        var first_line = true
        for (line in 0..lines.size) {
            let row = lines[line].strip()
            if (row == "") {
                continue
            }
            let columns = row.split(",").map({s => s.strip()})
            if (first_line) {
                title = ArrayList<String>(columns)
                first_line = false
            } else {
                data.add(ArrayList<String>(columns))
            }
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let file = File.open(file_name, mode: "w")
        if (file == None<File>) {
            return 0
        }
        var content = ""
        for (i in 0..data.size) {
            let row = data[i]
            for (j in 0..row.size) {
                content += row[j]
                if (j < row.size - 1) {
                    content += ","
                }
            }
            if (i < data.size - 1) {
                content += "\n"
            }
        }
        file.getOrThrow().write(content)
        file.getOrThrow().close()
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = read_csv(save_file_name)
        if (data.size == 0 && title.size == 0) {
            return 0
        }

        let new_data = ArrayList<ArrayList<String>>()
        let new_title = ArrayList<String>(title)

        let processed_column = ArrayList<String>()
        for (row in 0..data.size) {
            if (N < 0 || N >= data[row].size) {
                return 0
            }
            let cell = data[row][N]
            let upper_cell = cell.toUpperCase()
            processed_column.add(upper_cell)
        }

        new_data.add(processed_column)

        let new_file_name = save_file_name.replace(".csv", "_process.csv")
        return write_csv(new_data, new_file_name)
    }
}

