class CSVProcessor {

    /*
    This is a class for processing CSV files, including reading and writing CSV data, as well as processing specific operations and saving as a new CSV file.
    */

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file = File.open(file_name, mode: "r")
        if (file == None<File>) {
            return (ArrayList<String>(), ArrayList<ArrayList<String>>())
        }
        let content = file.getOrThrow().readAll()
        file.getOrThrow().close()

        let lines = content.split("\n")
        let title_line = lines[0]
        let title = ArrayList<String>(title_line.split(",").map({s => s.trim()}))

        let data = ArrayList<ArrayList<String>>()
        for (i in 1..lines.size) {
            let line = lines[i].trim()
            if (line == "") { continue }
            let fields = ArrayList<String>(line.split(",").map({s => s.trim()}))
            data.add(fields)
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let file = File.open(file_name, mode: "w")
        if (file == None<File>) {
            return 0
        }
        let writer = file.getOrThrow()
        for (row in data) {
            let line = ""
            for (i in 0..row.size) {
                line = line + row[i]
                if (i < row.size - 1) {
                    line = line + ","
                }
            }
            writer.write(line + "\n")
        }
        writer.close()
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = read_csv(save_file_name)
        if (data.size == 0 && title.size <= N) {
            return 0
        }

        let new_data = ArrayList<ArrayList<String>>()
        for (row in data) {
            if (N < row.size) {
                let value = row[N].toUpper()
                let new_row = ArrayList<String>([value])
                new_data.add(new_row)
            }
        }

        let new_title = ArrayList<String>(title) // keep full title for output structure
        let output_data = ArrayList<ArrayList<String>>()
