import std.collection.*
import std.fs.*
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file = File(file_name)
        if (!file.exists()) {
            return (ArrayList<String>(), ArrayList<ArrayList<String>>())
        }

        let lines = ArrayList<String>()
        let reader = FileReader(file)
        var line = reader.readln()
        while (line != None<String>) {
            lines.add(line.getOrThrow())
            line = reader.readln()
        }
        reader.close()

        if (lines.size == 0) {
            return (ArrayList<String>(), ArrayList<ArrayList<String>>())
        }

        let title = ArrayList<String>()
        let data = ArrayList<ArrayList<String>>()

        // Split first line as title
        let title_parts = split_with_comma(lines[0])
        for (part in title_parts) {
            title.add(part.trim())
        }

        // Process remaining lines
        for (i in 1..lines.size) {
            let row = ArrayList<String>()
            let parts = split_with_comma(lines[i])
            for (part in parts) {
                row.add(part.trim())
            }
            data.add(row)
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let file = File(file_name)
        let writer = FileWriter(file)

        for (row in data) {
            let line = ArrayList<String>()
            for (cell in row) {
                // Simple escaping: if cell contains comma, wrap in quotes
                if (cell.contains(",") || cell.contains("\"") || cell.contains("\n")) {
                    let escaped = cell.replace("\"", "\"\"")
                    line.add("\"${escaped}\"")
                } else {
                    line.add(cell)
                }
            }
            writer.writeln(join(line, ","))
        }

        writer.close()
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = read_csv(save_file_name)
        if (data.size == 0 && title.size == 0) {
            return 0
        }

        // Create new file name
        let dot_index = save_file_name.lastIndexOf(".")
        let base_name = if (dot_index != -1) {
            save_file_name.substring(0, dot_index)
        } else {
            save_file_name
        }
        let ext = if (dot_index != -1) {
            save_file_name.substring(dot_index)
        } else {
            ".csv"
        }
        let new_file_name = "${base_name}_process${ext}"

        // Check if N is valid
        if (N < 0 || (title.size <= N && data.size > 0 && data[0].size <= N)) {
            return 0
        }

        let new_data = ArrayList<ArrayList<String>>()

        // Add title row (unchanged)
        let title_row = ArrayList<String>()
        for (t in title) {
            title_row.add(t)
        }
        new_data.add(title_row)

        // Process Nth column from each data row
        for (row in data) {
            if (row.size > N) {
                let clean_val = row[N].strip() // strip extra spaces
                let upper_val = clean_val.toUpperCase()
                let new_row = ArrayList<String>([upper_val])
                new_data.add(new_row)
            }
        }

        let result = write_csv(new_data, new_file_name)
        return result
    }

    // Helper to split string by comma, handling basic quoted fields
    private func split_with_comma(s: String): ArrayList<String> {
        let result = ArrayList<String>()
        let parts = ArrayList<String>()
        var in_quotes = false
        var current = ""
        let runes = s.runes()

        for (r in runes) {
            if (r == r'"') {
                in_quotes = !in_quotes
                current = current + r.toString()
            } else if (r == r',' && !in_quotes) {
                parts.add(current)
                current = ""
            } else {
                current = current + r.toString()
            }
        }
        parts.add(current)

        // Unquote fields if needed
        for (p in parts) {
            let trimmed = p.trim()
            if (trimmed.startsWith("\"") && trimmed.endsWith("\"")) {
                let unquoted = trimmed.substring(1, trimmed.size - 1).replace("\"\"", "\"")
                result.add(unquoted)
            } else {
                result.add(trimmed)
            }
        }

        return result
    }

    // Helper to join strings with delimiter
    private func join(arr: ArrayList<String>, sep: String): String {
        if (arr.size == 0) return ""
        var result = arr[0]
        for (i in 1..arr.size) {
            result = result + sep + arr[i]
        }
        return result
    }
}

