import std.collection.HashMap
import std.collection.ArrayList
import std.math.round
import std.math.abs
import std.sort.sort

class DataStatistics {

    public func mean(data: ArrayList<Int64>): Float64 {
        let total: Int64 = 0
        for (i in 0..data.size) {
            total = total + data[i]
        }
        let avg: Float64 = total as Float64 / data.size as Float64
        return round(avg * 100.0) / 100.0
    }

    public func median(data: ArrayList<Int64>): Float64 {
        let sorted_data = ArrayList<Int64>(data)
        sort(sorted_data)
        let n = sorted_data.size
        if (n % 2 == 1) {
            let mid = sorted_data[n / 2]
            return round((mid as Float64) * 100.0) / 100.0
        } else {
            let mid1 = sorted_data[n / 2 - 1]
            let mid2 = sorted_data[n / 2]
            let avg = (mid1 + mid2) as Float64 / 2.0
            return round(avg * 100.0) / 100.0
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let freq_map = HashMap<Int64, Int64>()
        for (i in 0..data.size) {
            let val = data[i]
            if (freq_map.contains(val)) {
                freq_map[val] = freq_map[val] + 1
            } else {
                freq_map.add(val, 1)
            }
        }

        let max_count = ref 0
        for ((_, count) in freq_map) {
            if (count > max_count^) {
                max_count^ = count
            }
        }

        let modes = ArrayList<Int64>()
        for ((val, count) in freq_map) {
            if (count == max_count^) {
                modes.add(val)
            }
        }

        sort(modes)
        return modes
    }
}

