class DataStatistics2 {

    /*
    This is a class for performing data statistics, supporting to get the sum, minimum, maximum, variance, standard deviation, and correlation of a given dataset.
    */

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        /*
        Initialize Data List
        :param data:ArrayList<Float64>
        */
        this.data = data
    }

    public func get_sum(): Float64 {
        /*
        Calculate the sum of data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_sum()
        10.0
        */
        var sum: Float64 = 0.0
        for (i in 0..data.size) {
            sum = sum + data[i]
        }
        return sum
    }

    public func get_min(): Float64 {
        /*
        Calculate the minimum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_min()
        1.0
        */
        var min: Float64 = data[0]
        for (i in 1..data.size) {
            if (data[i] < min) {
                min = data[i]
            }
        }
        return min
    }

    public func get_max(): Float64 {
        /*
        Calculate the maximum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_max()
        4.0
        */
        var max: Float64 = data[0]
        for (i in 1..data.size) {
            if (data[i] > max) {
                max = data[i]
            }
        }
        return max
    }

    public func get_variance(): Float64 {
        /*
        Calculate variance, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_variance()
        1.25
        */
        let n: Float64 = data.size as Float64
        let mean: Float64 = get_sum() / n
        var sum_sq: Float64 = 0.0
        for (i in 0..data.size) {
            let diff = data[i] - mean
            sum_sq = sum_sq + diff * diff
        }
        let variance = sum_sq / n
        return round(variance * 100.0) / 100.0
    }

    public func get_std_deviation(): Float64 {
        /*
        Calculate standard deviation, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_std_deviation()
        1.12
        */
        let variance = get_variance()
        let std_dev = sqrt(variance)
        return round(std_dev * 100.0) / 100.0
    }

    public func get_correlation(): Float64 {
        /*
        Calculate correlation
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_correlation()
        1.0
        */
        // Assuming this is correlation with index positions (linear trend)
        // This matches the expected output of 1.0 for [1.0, 2.0, 3.0, 4.0]
        let n = data.size
        if (n == 0) { return 0.0 }

        // Create index array: 0, 1, 2, ..., n-1
        var indices = ArrayList<Float64>()
        for (i in 0..n) {
            indices.add(i as Float64)
        }

        let mean_x = DataStatistics2(indices).get_sum() / (n as Float64)
        let mean_y = get_sum() / (n as Float64)

        var cov: Float64 = 0.0
        var var_x: Float64 = 0.0
        var var_y: Float64 = 0.0

        for (i in 0..n) {
            let xi = indices[i] - mean_x
            let yi = data[i] - mean_y
            cov = cov + xi * yi
            var_x = var_x + xi * xi
            var_y = var_y + yi * yi
        }

        if (var_x == 0.0 || var_y == 0.0) {
            return 0.0
        }

        let corr = cov / sqrt(var_x * var_y)
        return round(corr * 100.0) / 100.0
    }
}

