            let dy = data2[i] - mean2
            cov += dx * dy
            var1 += dx * dx
            var2 += dy * dy
        }

        if (var1 == 0.0 || var2 == 0.0) {
            return 0.0
        }

        return cov / (sqrt(var1) * sqrt(var2))
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size
        if (n < 3) {
            return 0.0
        }

        // Mean
        var sum = 0.0
        for (i in 0..n) {
            sum += data[i]
        }
        let mean = sum / n

        // Variance and third central moment
        var m2 = 0.0
        var m3 = 0.0
        for (i in 0..n) {
            let dx = data[i] - mean
            m3 += dx * dx * dx
            m2 += dx * dx
        }
        let variance = m2 / n
        if (variance == 0.0) {
            return 0.0
        }

        let std_dev = sqrt(variance)
        let skew = (m3 / n) / (std_dev * std_dev * std_dev)
        return skew
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size
        if (n < 4) {
            return 0.0
        }

        // Mean
        var sum = 0.0
        for (i in 0..n) {
            sum += data[i]
        }
        let mean = sum / n

        // Fourth and second central moments
        var m4 = 0.0
        var m2 = 0.0
        for (i in 0..n) {
            let dx = data[i] - mean
            let dx2 = dx * dx
            m2 += dx2
            m4 += dx2 * dx2
        }
        let variance = m2 / n
        if (variance == 0.0) {
            return 0.0
        }

        let kurt = (m4 / n) / (variance * variance) - 3.0
        return kurt
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let n = data.size
        let result = ArrayList<Float64>([])
        let coeff = 1.0 / (sqrt(2.0 * PI) * sigma)
        for (i in 0..n) {
            let x = data[i]
            let exponent = -0.5 * pow((x - mu) / sigma, 2.0)
            let value = coeff * exp(exponent)
            result.add(value, at: i)
        }
        return result
    }
}

