    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size
        if (n < 3) {
            return 0.0
        }

        // Mean
        var sum = 0.0
        for (i in 0..n) {
            sum += data[i]
        }
        let mean = sum / n

        // Sample standard deviation (using n-1)
        var variance = 0.0
        for (i in 0..n) {
            let diff = data[i] - mean
            variance += diff * diff
        }
        let std_dev = sqrt(variance / (n - 1))

        if (std_dev == 0.0) {
            return 0.0
        }

        // Third central moment (sample version)
        var skew = 0.0
        for (i in 0..n) {
            let diff = (data[i] - mean) / std_dev
            skew += diff * diff * diff
        }

        // Bias-corrected sample skewness: (n / ((n-1)*(n-2))) * sum(...)
        return (n / ((n - 1) * (n - 2))) * skew
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size
        if (n < 4) {
            return 0.0
        }

        // Mean
        var sum = 0.0
        for (i in 0..n) {
            sum += data[i]
        }
        let mean = sum / n

        // Standard deviation using sample variance (n-1)
        var variance = 0.0
        for (i in 0..n) {
            let diff = data[i] - mean
            variance += diff * diff
        }
        let std_dev = sqrt(variance / (n - 1))

        if (std_dev == 0.0) {
            return 0.0
        }

        // Fourth standardized moment
        var kurt = 0.0
        for (i in 0..n) {
            let z = (data[i] - mean) / std_dev
            kurt += z * z * z * z
        }

        // Bias-corrected sample kurtosis
        let result = ((n * (n + 1)) / ((n - 1) * (n - 2) * (n - 3))) * kurt
        let adjustment = (3 * (n - 1) * (n - 1)) / ((n - 2) * (n - 3))
        return result - adjustment
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        if (sigma <= 0.0) {
            let result = ArrayList<Float64>()
            for (i in 0..data.size) {
                result.add(0.0)
            }
            return result
        }

        let coef = 1.0 / (sqrt(2.0 * PI) * sigma)
        let exponent_base = 2.0 * sigma * sigma
        let result = ArrayList<Float64>()
        for (i in 0..data.size) {
            let exponent = -((data[i] - mu) * (data[i] - mu)) / exponent_base
            result.add(coef * exp(exponent))
        }
        return result
    }
