                let k = keyRunes[i % keyLen]
                let kShift = k - r'a'
                let shifted = ((r - r'a' - kShift + 26) % 26) + r'a'
                result += String::fromRune(shifted)
                i += 1
            } else if (r >= r'A' && r <= r'Z') {
                let k = keyRunes[i % keyLen]
                let kShift = k - r'a'
                let shifted = ((r - r'A' - kShift + 26) % 26) + r'A'
                result += String::fromRune(shifted)
                i += 1
            } else {
                result += String::fromRune(r)
            }
        }
        return result
    }

