            for (j in 0..n) {
                row.add(None<Rune>)
            }
            matrix.add(row)
        }

        var down: Bool = true
        var row = 0
        for (col in 0..n) {
            matrix[row][col] = Some<Rune>(r'A') // Mark positions that will be filled
            if (row == 0) {
                down = true
            } else if (row == rails - 1) {
                down = false
            }
            row += down ? 1 : -1
        }

        var idx = 0
        for (i in 0..rails) {
            for (j in 0..n) {
