        row = 0
        down = true
        for (col in 0..n) {
            result += String::fromRune(matrix[row][col].getOrThrow())
            if (row == 0) {
                down = true
            } else if (row == rails - 1) {
                down = false
            }
            row += down ? 1 : -1
        }

        return result
    }
