        for (r in ciphertext.runes()) {
            if (r >= r'a' && r <= r'z') {
                let offset = ((r - r'a') - shift_mod + 26) % 26
                result += String(r'a' + offset)
            } else if (r >= r'A' && r <= r'Z') {
                let offset = ((r - r'A') - shift_mod + 26) % 26
                result += String(r'A' + offset)
            } else {
