            return ciphertext
        }
        var result = ""
        var key_index = 0
        for (r in ciphertext.runes()) {
            if (r >= r'a' && r <= r'z') {
                let k = this.key.runes()[key_index % this.key.size]
                let k_shift = k - r'a'
                let offset = ((r - r'a') - k_shift + 26) % 26
                result += String(r'a' + offset)
                key_index += 1
            } else if (r >= r'A' && r <= r'Z') {
                let k = this.key.runes()[key_index % this.key.size]
                let k_shift = k - r'A'
                let offset = ((r - r'A') - k_shift + 26) % 26
                result += String(r'A' + offset)
                key_index += 1
            } else {
                result += String(r)
            }
        }
        return result
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        /*
        Deciphers the given ciphertext using the Rail Fence cipher
        :param encrypted_text: The ciphertext to decipher,String.
        :param rails: The number of rails to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.rail_fence_decipher('Hoo!el,Wrdl l', 3)
        'Hello, World!'

        */
        if (rails <= 1 || encrypted_text.size == 0) {
            return encrypted_text
        }
        let n = encrypted_text.size
        let cycle = 2 * rails - 2
        var rails_map = ArrayList<ArrayList<Rune>>()
        for (i in 0..rails) {
            rails_map.add(ArrayList<Rune>())
        }
        var index = 0
        while (index < encrypted_text.size) {
            for (i in 0..rails) {
                if (index < n) {
                    rails_map[i].add(encrypted_text.runes()[index])
                    index += 1
                } else {
                    break
                }
                if (i > 0 && i < rails - 1) {
                    // Add space for middle rails
                    for (j in i..i + 1) {
                        if (index < n) {
                            rails_map[j].add(r' ')
                            index += 1
                        } else {
                            break
                        }
                    }
                }
            }
            for (i in rails - 2..0) {
                if (index < n) {
                    rails_map[i].add(encrypted_text.runes()[index])
                    index += 1
                } else {
                    break
                }
                if (i > 0 && i < rails - 1) {
                    for (j in i..i + 1) {
                        if (index < n) {
                            rails_map[j].add(r' ')
                            index += 1
                        } else {
                            break
                        }
                    }
                }
            }
        }
        // Now reconstruct the result
        var result_array = Array<Rune>(n)
        let positions = ArrayList<(Int64, Int64)>()
        var pos_index = 0
        for (row in 0..rails) {
            let rail_length = rails_map[row].size
            for (col in 0..rail_length) {
                if (pos_index < n) {
                    positions.add((row, col))
                    pos_index += 1
                }
            }
        }
        // Sort positions by reading order
        let reading_order = { a: (Int64, Int64), b: (Int64, Int64) =>
            let (a_row, a_col) = a
            let (b_row, b_col) = b
            if (a_row != b_row) {
                a_row < b_row
            } else {
                a_col < b_col
            }
        }
        sort(positions, lessThan: reading_order)
        // Fill result
        for (i in 0..n) {
            let (row, _) = positions[i]
            result_array[i] = rails_map[row][0]
            rails_map[row].remove(at: 0)
        }
        return String(result_array)
    }
}

