class EightPuzzle {

    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([
            ArrayList<Int64>([1, 2, 3]),
            ArrayList<Int64>([4, 5, 6]),
            ArrayList<Int64>([7, 8, 0])
        ])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        for (i in 0..3) {
            for (j in 0..3) {
                if (state[i][j] == 0) {
                    return (i, j)
                }
            }
        }
        return (0, 0) // unreachable in valid puzzles
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        let new_state = deep_copy(state)
        let (i, j) = find_blank(new_state)
        match (direction) {
            case "up" => {
                if (i > 0) {
                    new_state[i][j] = new_state[i - 1][j]
                    new_state[i - 1][j] = 0
                }
            }
            case "down" => {
                if (i < 2) {
                    new_state[i][j] = new_state[i + 1][j]
                    new_state[i + 1][j] = 0
                }
            }
            case "left" => {
                if (j > 0) {
                    new_state[i][j] = new_state[i][j - 1]
                    new_state[i][j - 1] = 0
                }
            }
            case "right" => {
                if (j < 2) {
                    new_state[i][j] = new_state[i][j + 1]
                    new_state[i][j + 1] = 0
                }
            }
            case _ => {} // invalid direction, do nothing
        }
        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let moves = ArrayList<String>()
        let (i, j) = find_blank(state)

        if (i > 0) { moves.add("up") }
        if (i < 2) { moves.add("down") }
        if (j > 0) { moves.add("left") }
        if (j < 2) { moves.add("right") }

        return moves
    }

    public func solve(): ArrayList<String> {
        let queue = ArrayList<(ArrayList<ArrayList<Int64>>, ArrayList<String>)>()
        let visited = HashSet<String>()
        let start = (deep_copy(this.initial_state), ArrayList<String>())

        queue.add(start)
        visited.add(state_to_key(this.initial_state))

        while (queue.size > 0) {
            let (state, path) = queue[0]
            queue.remove(at: 0)

            if (is_goal(state)) {
                return path
            }

            let possible_moves = get_possible_moves(state)
            for (move_dir in possible_moves) {
                let new_state = move(state, move_dir)
                let state_key = state_to_key(new_state)

                if (!visited.contains(state_key)) {
                    visited.add(state_key)
                    let new_path = ArrayList<String>(path)
                    new_path.add(move_dir)
                    queue.add((new_state, new_path))
                }
            }
        }

        return ArrayList<String>() // no solution found
    }
}

// Helper to convert state to string key for HashSet
func state_to_key(state: ArrayList<ArrayList<Int64>>): String {
    var s = ""
    for (i in 0..3) {
        for (j in 0..3) {
            s = s + state[i][j].toString()
        }
    }
    return s
}

// Helper to check if state matches goal
func is_goal(state: ArrayList<ArrayList<Int64>>): Bool {
    for (i in 0..3) {
        for (j in 0..3) {
            if (state[i][j] != 1 + i * 3 + j && !(i == 2 && j == 2 && state[i][j] == 0)) {
                return false
            }
        }
    }
    return true
}

// Helper to deep copy 2D ArrayList
func deep_copy(state: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Int64>> {
    let new_state = ArrayList<ArrayList<Int64>>()
    for (i in 0..3) {
        let row = ArrayList<Int64>()
        for (j in 0..3) {
            row.add(state[i][j])
        }
        new_state.add(row)
    }
    return new_state
}

