                let offset = (r - lower_a + shift) % alphabet_size
                if (offset < 0) { offset = offset + alphabet_size }
                result.add(lower_a + offset)
            } else if (r >= upper_a && r <= ('Z'.toRune())) {
                let offset = (r - upper_a + shift) % alphabet_size
                if (offset < 0) { offset = offset + alphabet_size }
                result.add(upper_a + offset)
            } else {
