class EncryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        var result = ""
        for (r in plaintext.runes()) {
            if (r >= r'a' && r <= r'z') {
                let base = r'a'
                let offset = (r - base + shift) % 26
                if (offset < 0) {
                    offset += 26
                }
                result += String(r'a' + offset)
            } else if (r >= r'A' && r <= r'Z') {
                let base = r'A'
                let offset = (r - base + shift) % 26
                if (offset < 0) {
                    offset += 26
                }
                result += String(r'A' + offset)
            } else {
                result += String(r)
            }
        }
        return result
    }

    public func vigenere_cipher(plain_text: String): String {
        var result = ""
        let key_runes = key.toRuneArray()
        var key_index = 0
        for (r in plain_text.runes()) {
            if (r >= r'a' && r <= r'z') {
                let shift = key_runes[key_index % key_runes.size] - r'a'
                let base = r'a'
                let offset = (r - base + shift) % 26
                result += String(base + offset)
                key_index += 1
            } else if (r >= r'A' && r <= r'Z') {
                let shift = key_runes[key_index % key_runes.size] - r'a'
                let base = r'A'
                let offset = (r - base + shift) % 26
                result += String(base + offset)
                key_index += 1
            } else {
                result += String(r)
            }
        }
        return result
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        if (rails <= 1) {
            return plain_text
        }
        let n = plain_text.size
        var matrix = ArrayList<ArrayList<Rune>>()
        for (i in 0..rails) {
            matrix.add(ArrayList<Rune>())
        }
        var rail = 0
        var dir = 1
        for (i in 0..n) {
            matrix[rail].add(plain_text.runes().nth(i))
            rail += dir
            if (rail == 0 || rail == rails - 1) {
                dir = -dir
            }
        }
        var result = ""
        for (row in matrix) {
            for (ch in row) {
                result += String(ch)
            }
        }
        return result
    }
}

import std.collection.ArrayList

class EncryptionUtils {

    /*
    This is a class that provides methods for encryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the class with a key.
        :param key: The key to use for encryption, String.
        */
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        /*
        Encrypts the plaintext using the Caesar cipher.
        :param plaintext: The plaintext to encrypt, String.
        :param shift: The number of characters to shift each character in the plaintext, Int64.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.caesar_cipher("abc", 1)
        'bcd'
        */
        let runes = plaintext.toRuneArray()
        var result = ""
        for (r in runes) {
            let code = r.codePoint()
            // Only shift lowercase letters
            if (code >= 97 && code <= 122) {
                let shifted = (code - 97 + shift) % 26 + 97
                result += Rune.fromCodePoint(shifted)
            } else {
                result += r.toString()
            }
        }
        return result
    }

    public func vigenere_cipher(plain_text: String): String {
        /*
        Encrypts the plaintext using the Vigenere cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.vigenere_cipher("abc")
        'kfa'
        */
        let text_runes = plain_text.toRuneArray()
        let key_runes = this.key.toRuneArray()
        var result = ""
        var key_index = 0
        for (r in text_runes) {
            let code = r.codePoint()
            if (code >= 97 && code <= 122) {
                let key_char = key_runes[key_index % key_runes.size]
                let key_code = key_char.codePoint()
                let key_shift = key_code - 97
                let shifted = (code - 97 + key_shift) % 26 + 97
                result += Rune.fromCodePoint(shifted)
                key_index += 1
            } else {
                result += r.toString()
            }
        }
        return result
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        /*
        Encrypts the plaintext using the Rail Fence cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.rail_fence_cipher("abc", 2)
        'acb'
        */
        if (rails <= 1 || plain_text.size == 0) {
            return plain_text
        }
        let n = plain_text.size
        let fence = ArrayList<ArrayList<String>>()
        for (i in 0..rails) {
            fence.add(ArrayList<String>(), at: i)
        }
        var rail = 0
        var direction = 1  // 1 for down, -1 for up
        let runes = plain_text.toRuneArray()
        for (i in 0..n) {
            fence[rail].add(runes[i].toString())
            rail += direction
            if (rail == 0) {
                direction = 1
            } else if (rail == rails - 1) {
                direction = -1
            }
        }
        var result = ""
        for (row in fence) {
            for (ch in row) {
                result += ch
            }
        }
        return result
    }
}

