            10.0 * this.weight + 6.25 * this.height - 5.0 * this.age - 161.0
        }

        let factor = if (this.condition_judge() == 1) {
            1.2
        } else if (this.condition_judge() == -1) {
            1.6
        } else {
            1.4
        }

        return bmr * factor
    }
}

