class Interpolation {
    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()

        for (xi in x_interp) {
            // Find the interval [x[i], x[i+1]] that contains xi
            var idx = 0
            while (idx < x.size - 1 && xi > x[idx + 1]) {
                idx = idx + 1
            }

            if (idx >= x.size - 1) {
                // Extrapolate using last segment
                idx = x.size - 2
            }

            let x0 = x[idx]
            let x1 = x[idx + 1]
            let y0 = y[idx]
            let y1 = y[idx + 1]

            // Linear interpolation
            let yi = y0 + (xi - x0) * (y1 - y0) / (x1 - x0)
            result.add(yi)
        }

        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()

        for (i in 0..x_interp.size) {
            let xi = x_interp[i]
            let yi = y_interp[i]

            // Find x segment
            var x_idx = 0
            while (x_idx < x.size - 1 && xi > x[x_idx + 1]) {
                x_idx = x_idx + 1
            }
            if (x_idx >= x.size - 1) {
                x_idx = x.size - 2
            }

            // Find y segment
            var y_idx = 0
            while (y_idx < y.size - 1 && yi > y[y_idx + 1]) {
                y_idx = y_idx + 1
            }
            if (y_idx >= y.size - 1) {
                y_idx = y.size - 2
            }

            // 4 corner points
            let x0 = x[x_idx]
            let x1 = x[x_idx + 1]
            let y0 = y[y_idx]
            let y1 = y[y_idx + 1]

            let z00 = z[x_idx][y_idx]
            let z10 = z[x_idx + 1][y_idx]
            let z01 = z[x_idx][y_idx + 1]
            let z11 = z[x_idx + 1][y_idx + 1]

            // Bilinear interpolation
            let wx = (xi - x0) / (x1 - x0)
            let wy = (yi - y0) / (y1 - y0)

            let z_interp = (1 - wx) * (1 - wy) * z00 +
                           wx       * (1 - wy) * z10 +
                           (1 - wx) * wy       * z01 +
                           wx       * wy       * z11

            result.add(z_interp)
        }

        return result
    }
}

