        for (xi in x_interp) {
            // Find the interval [x[i], x[i+1]] containing xi
            var i = 0
            while (i < n - 1 && xi > x[i + 1]) {
                i = i + 1
            }

            // If xi is outside [x[0], x[n-1]], use nearest value (clamp)
            if (xi <= x[0]) {
                result.add(y[0])
            } else if (xi >= x[n - 1]) {
                result.add(y[n - 1])
            } else {
                // Linear interpolation
                let x0 = x[i]
                let x1 = x[i + 1]
                let y0 = y[i]
                let y1 = y[i + 1]
                let yi = y0 + (yi - x0) * (y1 - y0) / (x1 - x0)
                result.add(yi)
            }
        }

        return result
    }

