                j = j + 1
            }
            j = if (j >= m - 1) { m - 2 } else { j }

            // Get bounding coordinates
            let x0 = x[i]
            let x1 = x[i + 1]
            let y0 = y[j]
            let y1 = y[j + 1]
            let z00 = z[j][i]     // z(y0, x0)
            let z10 = z[j][i+1]   // z(y0, x1)
            let z01 = z[j+1][i]   // z(y1, x0)
            let z11 = z[j+1][i+1] // z(y1, x1)

            // Bi-linear interpolation
            let diff_x = (xi - x0) / (x1 - x0)
            let diff_y = (yi - y0) / (y1 - y0)

            let z0 = z00 * (1.0 - diff_x) + z10 * diff_x
            let z1 = z01 * (1.0 - diff_x) + z11 * diff_x
            let zi = z0 * (1.0 - diff_y) + z1 * diff_y

            result.add(zi)
        }

        return result
    }
}

