class Interpolation {
    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for (xi in x_interp) {
            let n = x.size
            var left = 0
            var right = n - 1

            // Binary search for the interval
            while (left < right - 1) {
                let mid = (left + right) / 2
                if (x[mid] < xi) {
                    left = mid
                } else {
                    right = mid
                }
            }

            // Linear interpolation
            let x0 = x[left]
            let x1 = x[right]
            let y0 = y[left]
            let y1 = y[right]

            if (x1 == x0) {
                result.add(y0)
            } else {
                let t = (xi - x0) / (x1 - x0)
                let yi = y0 + t * (y1 - y0)
                result.add(yi)
            }
        }
        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for (i in 0..x_interp.size) {
            let xi = x_interp[i]
            let yi = y_interp[i]

            // Find x interval
            var x_left = 0
            var x_right = x.size - 1
            while (x_left < x_right - 1) {
                let mid = (x_left + x_right) / 2
                if (x[mid] < xi) {
                    x_left = mid
                } else {
                    x_right = mid
                }
            }

            // Find y interval
            var y_bottom = 0
            var y_top = y.size - 1
            while (y_bottom < y_top - 1) {
                let mid = (y_bottom + y_top) / 2
                if (y[mid] < yi) {
                    y_bottom = mid
                } else {
                    y_top = mid
                }
            }

            // Get the four corner points
            let x0 = x[x_left]
            let x1 = x[x_right]
            let y0 = y[y_bottom]
            let y1 = y[y_top]

            let q11 = z[x_left][y_bottom]
            let q21 = z[x_right][y_bottom]
            let q12 = z[x_left][y_top]
            let q22 = z[x_right][y_top]

            // Bilinear interpolation
            let denom = (x1 - x0) * (y1 - y0)
            if (denom == 0.0) {
                result.add(q11)
            } else {
                let a = 1.0 / denom
                let b = (x1 - xi) * (y1 - yi) * q11
                let c = (xi - x0) * (y1 - yi) * q21
                let d = (x1 - xi) * (yi - y0) * q12
                let e = (xi - x0) * (yi - y0) * q22
                let zi = a * (b + c + d + e)
                result.add(zi)
            }
        }
        return result
    }
}

