            var y_idx = 0
            while (y_idx < y.size - 1 && yi > y[y_idx + 1]) {
                y_idx = y_idx + 1
            }
            if (y_idx >= y.size - 1) {
                y_idx = y.size - 2
            }

            // Get four corner points: q11=(x[x_idx], y[y_idx]), q21, q12, q22
