            let x1 = x[x_idx]
            let x2 = x[x_idx + 1]
            let y1 = y[y_idx]
            let y2 = y[y_idx + 1]

            // Interpolate in x direction
            let f_x1 = ((x2 - xi) * q11 + (xi - x1) * q21) / (x2 - x1)
            let f_x2 = ((x2 - xi) * q12 + (xi - x1) * q22) / (x2 - x1)

            // Interpolate in y direction
            let f_xy = ((y2 - yi) * f_x1 + (yi - y1) * f_x2) / (y2 - y1)

            result.add(f_xy)
        }
        return result
    }
}

