        // Assume x_interp and y_interp have the same size
        for (i in 0..x_interp.size) {
            let xi = x_interp[i]
            let yi = y_interp[i]

            // Find x interval
            var x_idx = 0
            while (x_idx < x.size - 1 && xi > x[x_idx + 1]) {
                x_idx = x_idx + 1
            }

            // Find y interval
            var y_idx = 0
            while (y_idx < y.size - 1 && yi > y[y_idx + 1]) {
