            let Q21 = z[x_idx + 1][y_idx]
            let Q12 = z[x_idx][y_idx + 1]
            let Q22 = z[x_idx + 1][y_idx + 1]

            // Bilinear interpolation
            let t = (xi - x0) / (x1 - x0)
            let u = (yi - y0) / (y1 - y0)

            let R1 = Q11 + t * (Q21 - Q11)
