class Interpolation {
    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for (xi in x_interp) {
            // If xi is outside the range, clamp to boundary
            if (xi <= x[0]) {
                result.add(y[0])
            } else if (xi >= x[x.size - 1]) {
                result.add(y[y.size - 1])
            } else {
                // Find the segment where xi lies
                var idx = 0
                while (idx < x.size - 1 && x[idx + 1] < xi) {
                    idx = idx + 1
                }
                // Linear interpolation
                let x0 = x[idx]
                let x1 = x[idx + 1]
                let y0 = y[idx]
                let y1 = y[idx + 1]
                let frac = (xi - x0) / (x1 - x0)
                let yi = y0 + frac * (y1 - y0)
                result.add(yi)
            }
        }
        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for (i in 0..x_interp.size) {
            let xi = x_interp[i]
            let yi = y_interp[i]
            // Clamp x and y to grid boundaries
            let x0_idx = max(0, min(binary_search(x, xi), x.size - 2))
            let y0_idx = max(0, min(binary_search(y, yi), y.size - 2))
            let x1_idx = x0_idx + 1
            let y1_idx = y0_idx + 1

            // Get the four nearest points
            let x0 = x[x0_idx]
            let x1 = x[x1_idx]
            let y0 = y[y0_idx]
            let y1 = y[y1_idx]

            let q11 = z[y0_idx][x0_idx]
            let q21 = z[y0_idx][x1_idx]
            let q12 = z[y1_idx][x0_idx]
            let q22 = z[y1_idx][x1_idx]

            // Perform bilinear interpolation
            let denom_x = x1 - x0
            let denom_y = y1 - y0
            let xd = (x1 - xi) / denom_x
            let xu = (xi - x0) / denom_x
            let yd = (y1 - yi) / denom_y
            let yu = (yi - y0) / denom_y

            let f_interp = xd * yd * q11 + xu * yd * q21 + xd * yu * q12 + xu * yu * q22
            result.add(f_interp)
        }
        return result
    }

    // Helper function: find the largest index i such that x[i] <= value
    private static func binary_search(arr: ArrayList<Float64>, value: Float64): Int64 {
        var left = 0
        var right = arr.size - 1
        while (left < right) {
            let mid = left + (right - left + 1) / 2
            if (arr[mid] <= value) {
                left = mid
            } else {
                right = mid - 1
            }
        }
        return left
    }
}

