class IpUtil {

    public static func is_valid_ipv4(ip_address: String): Bool {
        let parts = ip_address.split(".")
        if (parts.size != 4) {
            return false
        }

        for (part in parts) {
            if (part.size == 0 || part.size > 3) {
                return false
            }

            let bytes = part.toRuneArray()
            for (r in bytes) {
                if (r < r'0' || r > r'9') {
                    return false
                }
            }

            let num = part.parseInt()
            if (num.isNone()) {
                return false
            }
            let n = num.getOrThrow()
            if (n < 0 || n > 255) {
                return false
            }
            // Leading zeros are not allowed unless the number is zero itself
            if (part.size > 1 && part[0] == r'0') {
                return false
            }
        }
        return true
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        // Handle compressed zeros (::), but only one compression allowed
        let has_double_colon = ip_address.contains("::")
        let colon_count = ip_address.count(r':')

        // IPv6 must have at least one ':' and valid segment count
        if (colon_count < 2 || colon_count > 7) {
            if (!has_double_colon) {
                return false
            }
        }

        // Cannot have more than 7 colons even with compression
        if (colon_count > 7) {
            return false
        }

        // Split by '::'
        let segments = ip_address.split("::")
        let num_segments = segments.size

        if (num_segments > 2) {
            return false  // Invalid format, more than one '::'
        }

        let left = segments[0].split(":")
        let right = if (num_segments == 2) { segments[1].split(":") } else { [] }

        var total_segments = left.size + right.size

        // Check for leading or trailing empty segments due to ::
        let left_empty = segments[0].size == 0
        let right_empty = num_segments == 2 && segments[1].size == 0

        if (left_empty && right_empty && total_segments == 0) {
            return true  // "::" is valid
        }

        if (left_empty || right_empty) {
            total_segments += 1
        }

        // Reconstruct full list of 8 segments if compressed
        if (has_double_colon) {
            if (total_segments > 7) {
                return false
            }
        } else {
            if (total_segments != 8) {
                return false
            }
        }

        // Validate each segment
        for (seg in left) {
            if (seg.size == 0) {
                continue
            }
            if (seg.size > 4) {
                return false
            }
            for (r in seg.runes()) {
                if !((r >= r'0' && r <= r'9') ||
                     (r >= r'a' && r <= r'f') ||
                     (r >= r'A' && r <= r'F')) {
                    return false
                }
            }
        }

        for (seg in right) {
            if (seg.size == 0) {
                continue
            }
            if (seg.size > 4) {
                return false
            }
            for (r in seg.runes()) {
                if !((r >= r'0' && r <= r'9') ||
                     (r >= r'a' && r <= r'f') ||
                     (r >= r'A' && r <= r'F')) {
                    return false
                }
            }
        }

