        }

        for (part in 0..parts.size) {
            let p = parts[part]
            if (p.size == 0 || p.size > 3) {
                return false
            }

            for (c in 0..p.size) {
                if (!is_digit(p[c])) {
                    return false
                }
            }

            let num = p.to_int() ?? -1
            if (num < 0 || num > 255) {
                return false
            }
            if (p.size > 1 && p[0] == '0') {  // No leading zeros
                return false
            }
        }

        return true
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        if (ip_address.contains("::")) {
            let count = ip_address.count(":")
            if (count > 7) {
                return false  // Too many segments even with compression
            }
        }

        let parts = ip_address.split(":")
        if (parts.size == 0 || parts.size > 8) {
            return false
        }

        var seen_empty = false
        for (part in 0..parts.size) {
            let p = parts[part]
            if (p.size == 0) {
                if (seen_empty) {
                    return false  // Multiple empty parts not allowed (except ::)
                }
                seen_empty = true
                continue
            }
            if (p.size > 4) {
                return false
            }
            for (c in 0..p.size) {
                if (!is_hex_digit(p[c])) {
                    return false
                }
            }
        }

        return true
    }

    public static func get_hostname(ip_address: String): Option<String> {
        if (!is_valid_ipv4(ip_address) && !is_valid_ipv6(ip_address)) {
