        if (parts.size != 4) {
            return false
        }

        for (part in parts) {
            if (part.size == 0 || part.size > 3) {
                return false
            }

            for (c in part.runes()) {
                if (c < r'0' || c > r'9') {
                    return false
                }
            }

            let num = part.toInt()
            if (num < 0 || num > 255) {
                return false
            }

            // Leading zero check: "0", "00", "01" -> invalid except "0"
            if (part.size > 1 && part[0] == '0') {
                return false
            }
        }

        return true
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        // Handle compressed zeros (::)
        let double_colon_count = ip_address.countSubstr("::")
        if (double_colon_count > 1) {
            return false  // Invalid if more than one ::
        }

        let has_double_colon = double_colon_count == 1

        let parts = ip_address.split(":")
        var valid_parts_count = 0
        var compressed = false

        for (part in parts) {
            if (part.size == 0) {
                if (compressed) {
                    return false  // Multiple empty parts not allowed
                }
                compressed = true
                continue
            }

            if (part.size > 4) {
                return false
            }

            for (c in part.runes()) {
                let is_digit = c >= r'0' && c <= r'9'
                let is_a_to_f = c >= r'a' && c <= r'f'
                let is_A_to_F = c >= r'A' && c <= r'F'
                if (!is_digit && !is_a_to_f && !is_A_to_F) {
                    return false
                }
            }
            valid_parts_count += 1
        }

        // Valid IPv6 must have between 1 and 8 parts if compressed, up to 8 in full
        let expected_count = if (has_double_colon) {
            1 <= valid_parts_count && valid_parts_count <= 7
        } else {
            valid_parts_count == 8
        }

        return expected_count
    }

    public static func get_hostname(ip_address: String): Option<String> {
        // Validate IP first
        let is_ipv4 = IpUtil.is_valid_ipv4(ip_address)
        let is_ipv6 = IpUtil.is_valid_ipv6(ip_address)
        if (!is_ipv4 && !is_ipv6) {
            return None<String>
        }

        let hostname = gethostname(ip_address)
        if (hostname == "") {
            return None<String>
        }

        return Some<String>(hostname)
    }
}

