        let parts = ip_address.split(".")
        if (parts.size != 4) {
            return false
        }
        for (part in parts) {
            if (part.size == 0 || part.size > 3) {
                return false
            }
            let mut digits = true
            for (r in part.runes()) {
                if (r < r'0' || r > r'9') {
                    digits = false
                    break
                }
            }
            if (!digits) {
                return false
            }
            let num = part.parseInt()
            if (num < 0 || num > 255) {
                return false
            }
            // Leading zeros are not allowed unless the number is exactly "0"
            if (part.size > 1 && part[0] == '0') {
                return false
            }
        }
        return true
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        // Simplified IPv6 validation (full or compressed, no IPv4 embedded)
        if (ip_address.size == 0 || ip_address.size > 39) {
            return false
        }
        let parts = ip_address.split(":")
        let mut seen_empty = false
        let mut compress_count = 0  // Count of empty parts due to :: compression

        for (part in parts) {
            if (part.size == 0) {
                if (seen_empty) {
                    // Multiple empty groups without compression (e.g., :::)
                    return false
                }
                seen_empty = true
                compress_count += 1
            } else {
                if (part.size > 4) {
                    return false
                }
                for (r in part.runes()) {
                    let c = r.lower()
                    if (!((c >= r'0' && c <= r'9') || (c >= r'a' && c <= r'f'))) {
                        return false
                    }
                }
            }
        }

        // Valid if: either no compression and 8 parts, or with compression (at most one ::)
        if (compress_count == 0) {
            return parts.size == 8
        } else {
            // :: allows fewer than 8 parts
            return parts.size - compress_count < 8
        }
    }

    public static func get_hostname(ip_address: String): Option<String> {
        if (is_valid_ipv4(ip_address) || is_valid_ipv6(ip_address)) {
            let hostname = gethostname(ip_address)
            if (hostname == "") {
                return None<String>
            } else {
                return Some<String>(hostname)
            }
        } else {
            return None<String>
        }
    }
}

