        // Basic check: length and invalid characters
        if (ip_address == "" || ip_address.size > 39) { // Max IPv6 string length
            return false
        }

        let parts = ip_address.split(":")
        let num_parts = parts.size

        // IPv6 can have at most 8 parts unless using :: compression
        var compressed = false
        var valid_parts = 0

