func is_digit(c: Rune): Bool {
    return c >= r'0' && c <= r'9'
}

func is_hex_digit(c: Rune): Bool {
    return (c >= r'0' && c <= r'9') ||
           (c >= r'a' && c <= r'f') ||
           (c >= r'A' && c <= r'F')
}

func parseInt(s: String): Int64 {
    var result: Int64 = 0
    for (i in 0..s.size) {
        let c = s[i]
        if (c < r'0' || c > r'9') {
            break
        }
        result = result * 10 + (c as Int64 - r'0' as Int64)
    }
    return result
}

