        let parts = ip_address.split(".")
        if (parts.size != 4) {
            return false
        }
        for (part in parts) {
            if (part.empty()) {
                return false
            }
            let bytes = part.toRuneArray()
            for (r in bytes) {
                if (r < r'0' || r > r'9') {
                    return false
                }
            }
            let num = part.toInt()
            if (num < 0 || num > 255) {
                return false
            }
            // Check for leading zeros (e.g., "01") which are invalid
            if (num != 0 && part[0] == r'0') {
                return false
            }
            if (num == 0 && part.size > 1) {
                return false
            }
        }
        return true
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        // Handle compressed zeros (::)
        let double_colon_count = ip_address.count(r':') - 1
        if (double_colon_count > 1) {
            return false
        }

        let has_double_colon = ip_address.contains("::")
        let parts = ip_address.split(":")
        var valid_parts_count = 0
        var compressed = false

        for (i in 0..parts.size) {
            let part = parts[i]
            if (part.empty()) {
                if (i == 0 || i == parts.size - 1) {
                    continue  // Leading or trailing empty is allowed due to :: at start/end
                }
                // Only one :: is allowed, so after encountering it, rest should follow rules
                if (compressed) {
                    return false
                }
                compressed = true
                continue
            }
            // Each part must be 1-4 hex characters
            if (part.size > 4) {
                return false
            }
            let runes = part.runes()
            for (r in runes) {
                if (!((r >= r'0' && r <= r'9') || 
                      (r >= r'a' && r <= r'f') || 
                      (r >= r'A' && r <= r'F'))) {
                    return false
                }
            }
            valid_parts_count += 1
        }

        // Total number of 16-bit groups must be <= 8
        // If :: exists, we allow less than 8; otherwise must be exactly 8
        if (has_double_colon) {
            return valid_parts_count <= 7
        } else {
            return valid_parts_count == 8
        }
    }

    public static func get_hostname(ip_address: String): Option<String> {
        if (!is_valid_ipv4(ip_address) && !is_valid_ipv6(ip_address)) {
            return None<String>
        }
        let hostname_result = gethostname(ip_address)
        if (hostname_result == "") {
            return None<String>
        }
        return Some<String>(hostname_result)
    }
