import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        // Compute Cohen's Kappa for a k x k confusion matrix (testData)
        // Assumption: testData is a k x k matrix where testData[i][j] = count of item i classified as j

        var total: Int64 = 0
        var expectedTotal: Int64 = 0

        // Marginal sums
        let rowSum = ArrayList<Int64>()
        let colSum = ArrayList<Int64>()

        for (_ in 0..k) {
            rowSum.add(0)
            colSum.add(0)
        }

        // Fill row and column sums
        for (i in 0..k) {
            for (j in 0..k) {
                let val = testData[i][j]
                total += val
                rowSum[i] += val
                colSum[j] += val
            }
        }

        // Observed agreement (Po): diagonal sum / total
        var po: Float64 = 0.0
        for (i in 0..k) {
            po += testData[i][i] as Float64
        }
        po /= total as Float64

        // Expected agreement (Pe): sum over classes of (rowSum[i] * colSum[i]) / total^2
        var pe: Float64 = 0.0
        for (i in 0..k) {
            pe += (rowSum[i] as Float64) * (colSum[i] as Float64)
        }
        pe /= (total as Float64) * (total as Float64)

        // Cohen's Kappa = (Po - Pe) / (1 - Pe), handling division by zero
        if (abs(1.0 - pe) < 1e-9) {
            return 1.0
        }
        return (po - pe) / (1.0 - pe)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        // Fleiss' Kappa for N subjects, k categories, n raters per subject
        // testData is N x k: each row is a subject, each column is count of raters assigning that category

        // Total number of classifications
        let totalClassifications = N * n

        // pij: proportion of subjects assigned to category j by rater i? No — here we have aggregate data.
        // We compute:
        //   pj = overall proportion of assignments to category j
        //   Pi = extent of agreement among raters on subject i

        let pj = ArrayList<Float64>() // Overall proportion for each category
        for (_ in 0..k) {
            pj.add(0.0)
        }

        var sumPi: Float64 = 0.0 // Sum of Pi over all subjects

        // Step 1: Compute Pi for each subject and update pj
        for (i in 0..N) {
            var pi: Float64 = 0.0 // Agreement for subject i
            for (j in 0..k) {
                let count = testData[i][j]
                pj[j] += count
                // Add squared terms for agreement
                pi += (count * count) as Float64
            }
            // Pi = (sum_{j} n_ij^2 - n) / (n(n-1))
            pi -= n as Float64
            if (n > 1) {
                pi /= (n * (n - 1)) as Float64
            } else {
                pi = 0.0
            }
            sumPi += pi
        }

        // Average Pi
        let pBar = sumPi / N as Float64

        // Normalize pj to get category proportions
        for (j in 0..k) {
            pj[j] /= totalClassifications as Float64
        }

        // Compute peBar: expected agreement by chance
        var peBar: Float64 = 0.0
        for (j in 0..k) {
            peBar += (pj[j] * pj[j])
        }

        // Fleiss' Kappa = (pBar - peBar) / (1 - peBar)
        if (abs(1.0 - peBar) < 1e-9) {
            return 1.0
        }
        return (pBar - peBar) / (1.0 - peBar)
    }
}

import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        // Compute Cohen's Kappa for a k x k confusion matrix (testData)
        // Assumption: testData is a k x k matrix where testdata[i][j] = count of instance i classified as j

        var total: Int64 = 0
        for (i in 0..k) {
            for (j in 0..k) {
                total += testData[i][j]
            }
        }

        // Compute agreement observed
        var observed_agreement: Float64 = 0.0
        for (i in 0..k) {
            observed_agreement += testData[i][i] as Float64
        }
        observed_agreement /= total as Float64

        // Compute expected agreement
        var expected_agreement: Float64 = 0.0
        for (j in 0..k) {
            var col_sum: Int64 = 0
            var row_sum: Int64 = 0
            for (i in 0..k) {
                row_sum += testData[j][i]
                col_sum += testData[i][j]
            }
            expected_agreement += ((row_sum as Float64) * (col_sum as Float64)) / ((total as Float64) * (total as Float64))
        }

        // Avoid division by zero
        if (abs(expected_agreement - 1.0) < 1e-9) {
            if (abs(observed_agreement - 1.0) < 1e-9) {
                return 1.0
            } else {
                return 0.0
            }
        }

        return (observed_agreement - expected_agreement) / (1.0 - expected_agreement)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        // Fleiss' Kappa for N subjects, k categories, n raters per subject
        // testData: N x k matrix, testData[i][j] = number of raters that assigned subject i to category j

        // Compute pj: proportion of all assignments to category j
        var pj: ArrayList<Float64> = ArrayList<Float64>()
        for (j in 0..k) {
            pj.add(0.0)
        }

        var total_assignments: Int64 = N * n

        for (j in 0..k) {
            var sum: Int64 = 0
            for (i in 0..N) {
                sum += testData[i][j]
            }
            pj[j] = (sum as Float64) / (total_assignments as Float64)
        }

        // Compute Pi for each subject i: extent of agreement among raters for subject i
        var pi: ArrayList<Float64> = ArrayList<Float64>()
        for (i in 0..N) {
            var sum_sq: Float64 = 0.0
            for (j in 0..k) {
                let count_ij = testData[i][j] as Float64
                sum_sq += count_ij * count_ij
            }
            let pi_i = (sum_sq - n as Float64) / (n as Float64 * (n as Float64 - 1.0))
            pi.add(pi_i)
        }

        // Mean of Pi
        var mean_pi: Float64 = 0.0
        for (i in 0..N) {
            mean_pi += pi[i]
        }
        mean_pi /= N as Float64

        // Expected mean of Pi under independence
        var mean_pe: Float64 = 0.0
        for (j in 0..k) {
            mean_pe += pj[j] * pj[j]
        }

        // Avoid division by zero
        if (abs(1.0 - mean_pe) < 1e-9) {
            if (abs(mean_pi - 1.0) < 1e-9) {
                return 1.0
            } else {
                return 0.0
            }
        }

        return (mean_pi - mean_pe) / (1.0 - mean_pe)
    }
}

