        this.board = create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        let board = ArrayList<ArrayList<String>>()
        let random = Random()

        for (i in 0..rows) {
            let row = ArrayList<String>()
            for (j in 0..cols) {
                let icon = ICONS[random.nextInt() % ICONS.size]
                row.add(icon)
            }
            board.add(row)
        }

        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let x1 = pos1[0], y1 = pos1[1]
        let x2 = pos2[0], y2 = pos2[1]
        let rows = BOARD_SIZE[0], cols = BOARD_SIZE[1]

        // Check if positions are within bounds
        if (x1 < 0 || x1 >= rows || y1 < 0 || y1 >= cols) { return false }
        if (x2 < 0 || x2 >= rows || y2 < 0 || y2 >= cols) { return false }

        // Positions must not be the same
        if (pos1 == pos2) { return false }

        // Icons must be the same
        if (board[x1][y1] != board[x2][y2]) { return false }

        // There must be a valid path
        return has_path(pos1, pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let x1 = pos1[0], y1 = pos1[1]
        let x2 = pos2[0], y2 = pos2[1]

        // If icons are different, no path
        if (board[x1][y1] != board[x2][y2]) { return false }

        // If same position, trivially connected
        if (pos1 == pos2) { return true }

        let visited = ArrayList<(Int64, Int64)>()
        return dfs(pos1, pos2, visited)
    }

    private func dfs(current: (Int64, Int64), target: (Int64, Int64), visited: ArrayList<(Int64, Int64)>): Bool {
        if (current == target) {
            return true
        }

        if (contains(visited, current)) {
            return false
        }

        visited.add(current)

        let x = current[0], y = current[1]
        let directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        let rows = BOARD_SIZE[0], cols = BOARD_SIZE[1]

        for (dir in directions) {
            let nx = x + dir[0]
            let ny = y + dir[1]
            let next = (nx, ny)

            if (nx < 0 || nx >= rows || ny < 0 || ny >= cols) { continue }

            // Only proceed if cell is not empty and not visited
            if (board[nx][ny] != " " && board[nx][ny] == board[x][y]) {
                if (dfs(next, target, visited)) {
                    return true
                }
            }
        }

        visited.remove(at: visited.size - 1)
        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        let x1 = pos1[0], y1 = pos1[1]
        let x2 = pos2[0], y2 = pos2[1]
        board[x1][y1] = " "
        board[x2][y2] = " "
    }

    public func is_game_over(): Bool {
        for (i in 0..BOARD_SIZE[0]) {
            for (j in 0..BOARD_SIZE[1]) {
                if (board[i][j] != " ") {
                    return false
                }
            }
        }
        return true
    }
}

