import std.collection.*
import std.sort.*

class Manacher {
    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        let left = center - diff
        let right = center + diff
        if left < 0 || right >= string.size {
            return 0
        }
        if string[left] != string[right] {
            return 0
        }
        return 1 + palindromic_length(center, diff + 1, string)
    }

    public func palindromic_string(): String {
        let processed = this.preprocess()
        let n = processed.size
        var radius = Array<Int64>(n, 0)
        var center = 0
        var right = 0

        for (i in 0..n) {
            let mirror = 2 * center - i
            if i < right {
                radius[i] = min(right - i, radius[mirror])
            }

            let diff = radius[i] + 1
            let expand = palindromic_length(i, diff, processed)
            radius[i] += expand

            if i + radius[i] > right {
                center = i
                right = i + radius[i]
            }
        }

        let max_len = var max = 0
        let center_index = var center_idx = 0
        for (i in 0..n) {
            if radius[i] > max {
                max = radius[i]
                center_idx = i
            }
        }

        let start = (center_idx - max_len) / 2
        return this.input_string[start..start + max_len]
    }

    private func preprocess(): String {
        let sb = ArrayList<Rune>()
        sb.add(r'|')
        for (ch in this.input_string.runes()) {
            sb.add(ch)
            sb.add(r'|')
        }
        return sb.join("")
    }
}

