        // Extract the actual palindrome from processed string
        let mut start = center_index - max_len
        let mut end = center_index + max_len
        let mut result = ""
        while start <= end {
            if processed[start] != '|' {
                result = result + String(processed[start])
            }
            start = start + 1
        }

