        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        var map = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            var row = ArrayList<String>()
            for (j in 0..n) {
                row.add("0")
            }
            map.add(row)
        }

        var mines_placed = 0
        let rand = Random()
        while (mines_placed < k) {
            let x = rand.nextInt(0, n)
            let y = rand.nextInt(0, n)
            if (map[x][y] != "X") {
                map[x][y] = "X"
                mines_placed += 1

                for (dx in -1..2) {
                    for (dy in -1..2) {
                        let nx = x + dx
                        let ny = y + dy
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && map[nx][ny] != "X") {
                            let val = map[nx][ny].parse<Int64>() ?? 0
                            map[nx][ny] = (val + 1).toString()
                        }
                    }
                }
            }
        }
        return map
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        var player_map = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            var row = ArrayList<String>()
            for (j in 0..n) {
                row.add("-")
            }
            player_map.add(row)
        }
        return player_map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..n) {
            for (j in 0..n) {
                if (map[i][j] == "-") {
                    if (minesweeper_map[i][j] != "X") {
                        return false
                    }
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (x < 0 || x >= n || y < 0 || y >= n) {
            return player_map
        }

        if (player_map[x][y] != "-") {
            return player_map
        }

        if (minesweeper_map[x][y] == "X") {
            player_map[x][y] = "X"
            return false
        }

        player_map[x][y] = minesweeper_map[x][y]

        if (player_map[x][y] == "0") {
            for (dx in -1..2) {
                for (dy in -1..2) {
                    let nx = x + dx
                    let ny = y + dy
                    if (nx >= 0 && nx < n && ny >= 0 && ny < n && player_map[nx][ny] == "-") {
                        sweep(nx, ny)
                    }
                }
            }
        }

        if (check_won(player_map)) {
            return true
        }

        return player_map
    }
}

