class MinesweeperGame {

    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        // Initialize n x n map with "0"
        var map = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            var row = ArrayList<String>()
            for (j in 0..n) {
                row.add("0", at: j)
            }
            map.add(row, at: i)
        }

        // Place k mines randomly
        var placed = 0
        let rand = Random()
        while (placed < k) {
            let x = rand.nextInt(0, n - 1)
            let y = rand.nextInt(0, n - 1)
            if (map[x][y] != "X") {
                map[x][y] = "X"
                placed += 1

                // Update neighbor counts (8 directions)
                for (dx in -1..2) {
                    for (dy in -1..2) {
                        let nx = x + dx
                        let ny = y + dy
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && map[nx][ny] != "X") {
                            let val = map[nx][ny].parseOrThrow<Int64>() + 1
                            map[nx][ny] = val.toString()
                        }
                    }
                }
            }
        }
        return map
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        var map = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            var row = ArrayList<String>()
            for (j in 0..n) {
                row.add("-", at: j)
            }
            map.add(row, at: i)
        }
        return map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..n) {
            for (j in 0..n) {
                if (map[i][j] == "-") {
                    if (minesweeper_map[i][j] != "X") {
                        return false
                    }
                } else if (minesweeper_map[i][j] == "X" && map[i][j] != "-") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (x < 0 || x >= n || y < 0 || y >= n) {
            return player_map  // Invalid coordinates
        }

        // If already revealed, do nothing
        if (player_map[x][y] != "-") {
            return player_map
        }

        // If player hits a mine
        if (minesweeper_map[x][y] == "X") {
            player_map[x][y] = "X"
            return true  // Game over
        }

        // Use flood fill for "0"
        let queue = ArrayList<(Int64, Int64)>()
        queue.add((x, y))

        while (queue.size > 0) {
            let (cx, cy) = queue[0]
            queue.remove(at: 0)

            if (player_map[cx][cy] != "-") {
                continue
            }

            player_map[cx][cy] = minesweeper_map[cx][cy]

            // Automatically reveal neighbors if current is "0"
            if (minesweeper_map[cx][cy] == "0") {
                for (dx in -1..2) {
                    for (dy in -1..2) {
                        let nx = cx + dx
                        let ny = cy + dy
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && player_map[nx][ny] == "-") {
                            queue.add((nx, ny), at: queue.size)
                        }
                    }
                }
            }
        }

        // Check if the player has won
        if (check_won(player_map)) {
            return true
        }

        return player_map
    }
}

