                row.add("0")
            }
            map.add(row)
        }

        // Place k mines randomly
        let rand = Random()
        var minesPlaced = 0_int64
        while (minesPlaced < k) {
            let x = rand.next() % n
            let y = rand.next() % n
            if (map[x][y] != "X") {
                map[x][y] = "X"
                minesPlaced = minesPlaced + 1

                // Increment neighbor counts
                for (dx in -1..2) {
                    for (dy in -1..2) {
                        let nx = x + dx
                        let ny = y + dy
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && map[nx][ny] != "X") {
                            let val = map[nx][ny].parseOrThrow<Int64>() + 1
                            map[nx][ny] = val.toString()
                        }
                    }
