            for (j in 0..n) {
                row.add("-")
            }
            map.add(row)
        }
        return map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..n) {
            for (j in 0..n) {
                if (map[i][j] == "-") {
                    // If player hasn't revealed a non-mine cell, game not won
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        // Check if out of bounds
        if (x < 0 || x >= n || y < 0 || y >= n) {
            return "Invalid coordinates"
        }

        // If already revealed, do nothing
        if (player_map[x][y] != "-") {
            return player_map
        }

        // If mine is hit
        if (minesweeper_map[x][y] == "X") {
            // Player loses
            return false
        }

        // Reveal cell
        player_map[x][y] = minesweeper_map[x][y]

        // Auto-reveal surrounding cells if it's "0"
        if (minesweeper_map[x][y] == "0") {
            for (dx in -1..2) {
                for (dy in -1..2) {
                    let nx = x + dx
                    let ny = y + dy
                    if (nx >= 0 && nx < n && ny >= 0 && ny < n && player_map[nx][ny] == "-") {
                        sweep(nx, ny)  // Recursive sweep
                    }
                }
            }
        }

        // Check if player has won
        if (check_won(player_map)) {
            return true
        }

        return player_map
    }
