class MinesweeperGame {

    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        // Initialize map with "0"
        var map = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            var row = ArrayList<String>()
            for (j in 0..n) {
                row.add("0", at: j)
            }
            map.add(row, at: i)
        }

        // Place mines randomly
        let rand = Random()
        var mines_placed = 0
        while (mines_placed < k) {
            let x = rand.nextInt(0, n - 1)
            let y = rand.nextInt(0, n - 1)
            if (map[x][y] != "X") {
                map[x][y] = "X"
                mines_placed += 1

                // Update neighbor counts
                for (dx in -1..2) {
                    for (dy in -1..2) {
                        let nx = x + dx
                        let ny = y + dy
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && map[nx][ny] != "X") {
                            let val = map[nx][ny].parse<Int64>() ?? 0
                            map[nx][ny] = "${val + 1}"
                        }
                    }
                }
            }
        }
        return map
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        var player_map = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            var row = ArrayList<String>()
            for (j in 0..n) {
                row.add("-", at: j)
            }
            player_map.add(row, at: i)
        }
        return player_map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..n) {
            for (j in 0..n) {
                let player_cell = map[i][j]
                let actual_cell = minesweeper_map[i][j]
                if (actual_cell != "X" && player_cell == "-") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        // If clicked on a mine, game over
        if (minesweeper_map[x][y] == "X") {
            return false
        }

        // Reveal the cell
        player_map[x][y] = minesweeper_map[x][y]

        // If it's "0", perform flood fill
        if (minesweeper_map[x][y] == "0") {
            let visited = ArrayList<ArrayList<Bool>>()
            for (i in 0..n) {
                var row = ArrayList<Bool>()
                for (j in 0..n) {
                    row.add(false, at: j)
                }
                visited.add(row, at: i)
            }

            var stack = ArrayList<(Int64, Int64)>()
            stack.add((x, y))
            visited[x][y] = true

            while (stack.size > 0) {
                let (cx, cy) = stack.remove(at: 0)
                for (dx in -1..2) {
                    for (dy in -1..2) {
                        let nx = cx + dx
                        let ny = cy + dy
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny]) {
                            visited[nx][ny] = true
                            if (minesweeper_map[nx][ny] == "0") {
                                player_map[nx][ny] = "0"
                                stack.add((nx, ny))
                            } else if (minesweeper_map[nx][ny] != "X") {
                                player_map[nx][ny] = minesweeper_map[nx][ny]
                            }
                        }
                    }
                }
            }
        }

        // Check if player has won
        if (check_won(player_map)) {
            return true
        }

        return player_map
    }
}

