            for (j in 0..n) {
                row.add("0")
            }
            map.add(row)
        }

        var placed = 0
        let rand = Random()
        while (placed < k) {
            let i = rand.nextInt(0, n)
            let j = rand.nextInt(0, n)
            if (map[i][j] != "X") {
                map[i][j] = "X"
                placed += 1
                for (di in -1..2) {
                    for (dj in -1..2) {
                        let ni = i + di
                        let nj = j + dj
                        if (ni >= 0 && ni < n && nj >= 0 && nj < n && map[ni][nj] != "X") {
                            let val = map[ni][nj].parseInt() ?? 0
                            map[ni][nj] = (val + 1).toString()
                        }
                    }
                }
            }
