class MusicPlayer {

    var playlist: ArrayList<String>
    var current_song: Option<String>
    var volume: Int64

    public init() {
        this.playlist = ArrayList<String>()
        this.current_song = None
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        this.playlist.add(song)
    }

    public func remove_song(song: String): Unit {
        this.playlist.remove(song)
    }

    public func play(): Option<String> {
        if (this.playlist.size == 0) {
            return None
        }
        if (this.current_song == None) {
            return None
        }
        return this.current_song
    }

    public func stop(): Bool {
        if (this.current_song == None) {
            return false
        }
        this.current_song = None
        return true
    }

    public func switch_song(): Bool {
        if (this.playlist.size == 0 || this.current_song == None) {
            return false
        }
        let index = find_index(this.current_song.getOrThrow())
        if (index == -1) {
            return false
        }
        let next_index = (index + 1) % this.playlist.size
        this.current_song = Some(this.playlist[next_index])
        return true
    }

    public func previous_song(): Bool {
        if (this.playlist.size == 0 || this.current_song == None) {
            return false
        }
        let index = find_index(this.current_song.getOrThrow())
        if (index == -1) {
            return false
        }
        let prev_index = (index - 1 + this.playlist.size) % this.playlist.size
        this.current_song = Some(this.playlist[prev_index])
        return true
    }

    public func set_volume(volume: Int64): Bool {
        if (volume < 0 || volume > 100) {
            return false
        }
        this.volume = volume
        return true
    }

    public func shuffle(): Bool {
        if (this.playlist.size == 0) {
            return false
        }
        let rand = Random()
        var i = this.playlist.size - 1
        while (i > 0) {
            let j = rand.next_int(max: i + 1)
            let temp = this.playlist[i]
            this.playlist[i] = this.playlist[j]
            this.playlist[j] = temp
            i = i - 1
        }
        return true
    }

    // Helper function to find index of current song
    private func find_index(song: String): Int64 {
        for (i in 0..this.playlist.size) {
            if (this.playlist[i] == song) {
                return i
            }
        }
        return -1
    }
}

