class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let words_list = ArrayList<ArrayList<String>>()
        let regex = Regex("[^a-zA-Z\\s]")

        for (str in string_list) {
            let cleaned = regex.replace_all(str, "")
            let lower = cleaned.to_lowercase()
            let words = lower.split(" ")
            let filtered_words = ArrayList<String>()

            for (word in words) {
                let trimmed = word.trim()
                if (trimmed.size > 0) {
                    filtered_words.add(trimmed)
                }
            }

            words_list.add(filtered_words)
        }

        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        let freq_map = HashMap<String, Int64>()

        for (word_list in words_list) {
            for (word in word_list) {
                let count = freq_map.get(word) ?? 0
                freq_map.add(word, count + 1)
            }
        }

        // Sort by frequency descending using sort on ArrayList of tuples
        let items = ArrayList<(String, Int64)>()
        for (k in freq_map.keys()) {
            items.add((k, freq_map[k]))
        }

        let lessThan = {a: (String, Int64), b: (String, Int64) => a[1] < b[1]}
        sort(items, lessThan: lessThan, descending: true)

        let result = HashMap<String, Int64>()
        let limit = if (items.size < 5) { items.size } else { 5 }
        for (i in 0..limit) {
            let k = items[i][0]
            let v = items[i][1]
            result.add(k, v)
        }

        return result
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words_list = self.process_data(string_list)
        return self.calculate_word_frequency(words_list)
    }
}

