import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let words_list = ArrayList<ArrayList<String>>()
        let regex = Regex("[^a-zA-Z\\s]")

        for (str in string_list) {
            let cleaned = regex.replace_all(str, "").to_lower()
            let words = cleaned.split(" ")
            let word_array = ArrayList<String>()

            for (word in words) {
                let trimmed = word.strip()
                if (trimmed.size > 0) {
                    word_array.add(trimmed)
                }
            }

            words_list.add(word_array)
        }

        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        let freq_map = HashMap<String, Int64>()

        for (word_list in words_list) {
            for (word in word_list) {
                let count = freq_map.get(word) ?? 0
                freq_map.add(word, count + 1)
            }
        }

        // Sort by frequency descending using key function
        let entries = freq_map.entries().to_array()
        let key = { entry: (String, Int64) => entry[1] }
        sort(entries, key: key, descending: true)

        let sorted_map = HashMap<String, Int64>()
        for (entry in entries) {
            sorted_map.add(entry[0], entry[1])
        }

        return sorted_map
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words_list = process_data(string_list)
        let freq_map = calculate_word_frequency(words_list)

        // Extract top 5
        let result = HashMap<String, Int64>()
        let entries = freq_map.entries().to_array()
        let limit = if (entries.size < 5) { entries.size } else { 5 }

        for (i in 0..limit) {
            let entry = entries[i]
            result.add(entry[0], entry[1])
        }

        return result
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let words_list = ArrayList<ArrayList<String>>()
        let regex = Regex("[^a-zA-Z\\s]")

        for (str in string_list) {
            let cleaned = regex.replace(str.lower(), with: "")
            let words = cleaned.split(sep: " ").filter({w: String => w.size > 0})
            let word_array = ArrayList<String>(words)
            words_list.add(word_array)
        }

        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        let freq_map = HashMap<String, Int64>()

        for (words in words_list) {
            for (word in words) {
                let current = freq_map.get(word) ?? 0
                freq_map.add(word, current + 1)
            }
        }

        // Sort by frequency descending
        let entries = freq_map.entries()
        let sorted_entries = entries.toArray()
        sort(sorted_entries, key: {e => -e.value}, descending: false)  // Use negative to simulate descending on value

        let result = HashMap<String, Int64>()
        let limit = 5
        let count = if (sorted_entries.size < limit) { sorted_entries.size } else { limit }

        for (i in 0..count) {
            let entry = sorted_entries[i]
            result.add(entry.key, entry.value)
        }

        return result
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words_list = self.process_data(string_list)
        return self.calculate_word_frequency(words_list)
    }
}

import std.convert.Formattable
import std.convert.Parsable
import std.convert.RadixConvertible

class NumberConverter {

    public static func decimal_to_binary(decimal_num: Int64): String {
        if (decimal_num == 0) {
            return "0"
        }
        let negative = decimal_num < 0
        var num = if (negative) { -decimal_num } else { decimal_num }
        var binary = ""
        while (num > 0) {
            binary = (num % 2).toString() + binary
            num = num / 2
        }
        return binary
    }

    public static func binary_to_decimal(binary_num: String): Int64 {
        var decimal = 0
        for (i in 0..binary_num.size) {
            let c = binary_num[i]
            decimal = decimal * 2 + (c == '1' ? 1 : 0)
        }
        return decimal
    }

    public static func decimal_to_octal(decimal_num: Int64): String {
        if (decimal_num == 0) {
            return "0"
        }
        let negative = decimal_num < 0
        var num = if (negative) { -decimal_num } else { decimal_num }
        var octal = ""
        while (num > 0) {
            octal = (num % 8).toString() + octal
            num = num / 8
        }
        return octal
    }

    public static func octal_to_decimal(octal_num: String): Int64 {
        var decimal = 0
        for (i in 0..octal_num.size) {
            let c = octal_num[i]
            decimal = decimal * 8 + (c - '0')
        }
        return decimal
    }

    public static func decimal_to_hex(decimal_num: Int64): String {
        if (decimal_num == 0) {
            return "0"
        }
        let negative = decimal_num < 0
        var num = if (negative) { -decimal_num } else { decimal_num }
        var hex = ""
        let digits = "0123456789abcdef"
        while (num > 0) {
            hex = digits[num % 16] + hex
            num = num / 16
        }
        return hex
    }

    public static func hex_to_decimal(hex_num: String): Int64 {
        var decimal = 0
        for (i in 0..hex_num.size) {
            var c = hex_num[i]
            var digit = 0
            if (c >= '0' && c <= '9') {
                digit = c - '0'
            } else if (c >= 'a' && c <= 'f') {
                digit = c - 'a' + 10
            } else if (c >= 'A' && c <= 'F') {
                digit = c - 'A' + 10
            }
            decimal = decimal * 16 + digit
        }
        return decimal
    }
}

