        }
        let mut num = decimal_num
        let mut binary = ""
        while (num > 0) {
            binary = (num % 2).toString() + binary
            num = num / 2
        }
        return binary
    }

    public static func binary_to_decimal(binary_num: String): Int64 {
        let mut decimal = 0: Int64
        let runes = binary_num.toRuneArray()
        for (i in 0..runes.size) {
            let r = runes[i]
            decimal = decimal * 2 + (r.toString().parse() ?? 0)
        }
        return decimal
    }

    public static func decimal_to_octal(decimal_num: Int64): String {
        if (decimal_num == 0) {
            return "0"
        }
        let mut num = decimal_num
        let mut octal = ""
        while (num > 0) {
            octal = (num % 8).toString() + octal
            num = num / 8
        }
        return octal
    }

    public static func octal_to_decimal(octal_num: String): Int64 {
        let mut decimal = 0: Int64
        let runes = octal_num.toRuneArray()
        for (i in 0..runes.size) {
            let r = runes[i]
            decimal = decimal * 8 + (r.toString().parse() ?? 0)
        }
        return decimal
    }

    public static func decimal_to_hex(decimal_num: Int64): String {
        if (decimal_num == 0) {
            return "0"
        }
        let mut num = decimal_num
        let mut hex = ""
        let digits = "0123456789abcdef"
        while (num > 0) {
            let index = (num % 16): Int64
            hex = digits[index] + hex
            num = num / 16
        }
        return hex
    }

    public static func hex_to_decimal(hex_num: String): Int64 {
        let mut decimal = 0: Int64
        let runes = hex_num.runes()
        for (r in runes) {
            decimal = decimal * 16
            match (r) {
                case r'0'..'9' => decimal = decimal + (r.toString().parse() ?? 0)
                case r'a' | r'A' => decimal = decimal + 10
                case r'b' | r'B' => decimal = decimal + 11
                case r'c' | r'C' => decimal = decimal + 12
                case r'd' | r'D' => decimal = decimal + 13
                case r'e' | r'E' => decimal = decimal + 14
                case r'f' | r'F' => decimal = decimal + 15
                case _ => {}
            }
        }
        return decimal
    }
}

