class NumberConverter {

    public static func decimal_to_binary(decimal_num: Int64): String {
        if (decimal_num == 0) {
            return "0"
        }
        var num = decimal_num
        var binary = ""
        while (num > 0) {
            binary = (num % 2).toString() + binary
            num = num // 2
        }
        return binary
    }

    public static func binary_to_decimal(binary_num: String): Int64 {
        var decimal = 0: Int64
        for (i in 0..binary_num.size) {
            let bit = binary_num[i]
            decimal = decimal * 2 + (bit as Int64 - '0' as Int64)
        }
        return decimal
    }

    public static func decimal_to_octal(decimal_num: Int64): String {
        if (decimal_num == 0) {
            return "0"
        }
        var num = decimal_num
        var octal = ""
        while (num > 0) {
            octal = (num % 8).toString() + octal
            num = num // 8
        }
        return octal
    }

    public static func octal_to_decimal(octal_num: String): Int64 {
        var decimal = 0: Int64
        for (i in 0..octal_num.size) {
            let digit = octal_num[i]
            decimal = decimal * 8 + (digit as Int64 - '0' as Int64)
        }
        return decimal
    }

    public static func decimal_to_hex(decimal_num: Int64): String {
        if (decimal_num == 0) {
            return "0"
        }
        var num = decimal_num
        var hex = ""
        let digits = "0123456789abcdef"
        while (num > 0) {
            hex = digits[num % 16] + hex
            num = num // 16
        }
        return hex
    }

    public static func hex_to_decimal(hex_num: String): Int64 {
        var decimal = 0: Int64
        for (i in 0..hex_num.size) {
            var digit: Int64 = 0
            let c = hex_num[i]
            if (c >= '0' && c <= '9') {
                digit = c as Int64 - '0' as Int64
            } else if (c >= 'a' && c <= 'f') {
                digit = c as Int64 - 'a' as Int64 + 10
            } else if (c >= 'A' && c <= 'F') {
                digit = c as Int64 - 'A' as Int64 + 10
            }
            decimal = decimal * 16 + digit
        }
        return decimal
    }
}

