    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        let value = x ?? ""
        if (value == "") {
            return "ZERO ONLY"
        }
        return format_string(value)
    }

    public func format_string(x: String): String {
        // Remove leading zeros and whitespace
        var cleaned = x.trim()
        while (cleaned.size > 0 && cleaned[0] == '0') {
            cleaned = cleaned.substring(1)
        }
        if (cleaned == "" || cleaned == "0") {
            return "ZERO ONLY"
        }

        // Split into integer and decimal parts
        let parts = cleaned.split('.')
        let intPart = parts[0]
        let decimalPart = if (parts.size > 1) { parts[1] } else { "" }

        // Convert integer part
        var result = ""
        if (intPart == "0") {
            result = "ZERO"
        } else {
            result = trans_integer(intPart)
        }

        // Add "ONLY" at the end
        result = result + " ONLY"
        return result
    }

    private func trans_integer(s: String): String {
        // Break number into chunks of 3 digits from right
        var chunks: ArrayList<String> = ArrayList<String>()
        var temp = s
        while (temp.size > 0) {
            let start = if (temp.size >= 3) { temp.size - 3 } else { 0 }
            chunks.add(temp.substring(start), at: 0)
            temp = temp.substring(0, end: start)
        }

        var words = ""
        for (i in 0..chunks.size) {
            let chunk = chunks[i]
            let chunkWord = trans_three(chunk)
            if (chunkWord != "") {
                if (words != "") {
                    words = words + " " + chunkWord + " " + parse_more(chunks.size - i - 1)
                } else {
                    words = chunkWord + " " + parse_more(chunks.size - i - 1)
                }
            }
        }
        return words.trim()
    }

    public func trans_two(s: String): String {
        let n = s.parseOrThrow<Int64>()
        if (n == 0) {
            return ""
        } else if (n < 10) {
            return NUMBER[n.toInt64()]
        } else if (n < 20) {
            return NUMBER_TEEN[(n - 10).toInt64()]
        } else {
            let tens = n / 10
            let ones = n % 10
            if (ones == 0) {
                return NUMBER_TEN[(tens - 1).toInt64()]
            } else {
                return NUMBER_TEN[(tens - 1).toInt64()] + " " + NUMBER[ones.toInt64()]
            }
        }
    }

    public func trans_three(s: String): String {
        let n = s.parseOrThrow<Int64>()
        if (n == 0) {
            return ""
        }
        if (s.size == 1) {
            return trans_two("0" + s)
        } else if (s.size == 2) {
            return trans_two(s)
        } else {
            let hundreds = s[0].toString().parseOrThrow<Int64>()
            let remainder = s.substring(1)
            let remainderWord = trans_two(remainder)
            if (remainderWord == "") {
                return NUMBER[hundreds] + " HUNDRED"
            } else {
                return NUMBER[hundreds] + " HUNDRED AND " + remainderWord
            }
        }
    }

    public func parse_more(i: Int64): String {
        if (i < 0 || i >= NUMBER_MORE.size) {
            return ""
        }
        return NUMBER_MORE[i]
    }
}

