class NumberWordFormatter {

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        let value = x ?? ""
        if (value == "") {
            return "ZERO ONLY"
        }
        return this.format_string(value)
    }

    public func format_string(x: String): String {
        // Remove leading zeros and validate
        var num_str = x
        var i = 0
        while (i < num_str.size && num_str[i] == '0') {
            i += 1
        }
        if (i == num_str.size) {
            return "ZERO ONLY"
        }
        num_str = num_str.substr(i)

        // Split by groups of three from the right
        var groups: ArrayList<String> = ArrayList<String>()
        var temp = num_str
        while (temp.size > 3) {
            let len = temp.size
            groups.add(temp.substr(len - 3), at: 0)
            temp = temp.substr(0, len - 3)
        }
        groups.add(temp, at: 0)

        var result: ArrayList<String> = ArrayList<String>()

        for (i in 0..groups.size) {
            let group = groups[i]
            let group_value = this.trans_three(group)
            if (group_value != "") {
                if (i != groups.size - 1) {
                    let suffix = this.parse_more(groups.size - 1 - i)
                    if (suffix != "") {
                        result.add("${group_value} ${suffix}")
                    } else {
                        result.add(group_value)
                    }
                } else {
                    result.add(group_value)
                }
            }
        }

        var final = ""
        for (i in 0..result.size) {
            if (i == 0) {
                final = result[i]
            } else {
                final = "${final} ${result[i]}"
            }
        }

        return "${final} ONLY"
    }

    public func trans_two(s: String): String {
        if (s.size == 1) {
            return this.NUMBER[s[0] - '0']
        }
        if (s[0] == '0') {
            return this.NUMBER[s[1] - '0']
        }
        if (s[0] == '1') {
            return this.NUMBER_TEEN[s[1] - '0']
        }
        var tens = this.NUMBER_TEN[s[0] - '0' - 1]
        var ones = this.NUMBER[s[1] - '0']
        if (ones == "") {
            return tens
        } else {
            return "${tens} ${ones}"
        }
    }

    public func trans_three(s: String): String {
        var padded = s
        while (padded.size < 3) {
            padded = "0${padded}"
        }
        if (padded[0] == '0') {
            return this.trans_two(padded.substr(1))
        }
        var hundreds = "${this.NUMBER[padded[0] - '0']} HUNDRED"
        var rest = this.trans_two(padded.substr(1))
        if (rest == "") {
            return hundreds
        } else {
            return "${hundreds} AND ${rest}"
        }
    }

    public func parse_more(i: Int64): String {
        if (i < this.NUMBER_MORE.size) {
            return this.NUMBER_MORE[i]
        }
        return ""
    }
}

