        let length = integer_part.size
        let groups = (length + 2) / 3  // ceiling of length/3
        var group_index = 0

        for (i in 0..length:3) {
            let start = length - i - 3
            if (start < 0) {
                let chunk = integer_part.substring(0, length - i)
                let words = this.trans_three(chunk)
                if (words != "") {
                    if (result != "") {
                        result = words + " " + this.parse_more(group_index) + " " + result
                    } else {
                        result = words + " " + this.parse_more(group_index)
                    }
