        if (len == 1) {
            return this.NUMBER[s[0] - r'0']
        }
        if (len == 2) {
            let tens = s[0] - r'0'
            let ones = s[1] - r'0'
            if (tens == 1) {
                return this.NUMBER_TEEN[ones]
            } else if (ones == 0) {
                return this.NUMBER_TEN[tens - 1]
            } else {
