            let start = if (i >= 3) { i - 3 } else { 0 }
            let chunk = num_str[start..i]
            let chunk_len = chunk.size

            let chunk_word = trans_three(chunk)
            let suffix_index = group_count

            if (chunk_word != "") {
                if (result != "") {
                    result = chunk_word + " " + parse_more(suffix_index) + " " + result
                } else {
                    result = chunk_word + " " + parse_more(suffix_index)
                }
            }

            group_count = group_count + 1
            i = start
        }

        // Clean up extra spaces
        return result.trim().replaceAll(" +", " ")
    }

    private func parse_decimal(num: String): String {
        var result = ""
        for (i in 0..num.size) {
            let digit = num[i]
            let index = digit.toInt()
            result = result + " " + NUMBER[index]
        }
        return result.trim()
    }

    public func trans_two(s: String): String {
        let n = s.toInt()
        if (n == 0) {
