        } else {
            let tens = n / 10
            let ones = n % 10
            if (ones == 0) {
                return this.NUMBER_TEN[tens - 1]
            } else {
                return this.NUMBER_TEN[tens - 1] + " " + this.NUMBER[ones]
            }
        }
    }

    public func trans_three(s: String): String {
        let n = s.parseOrZero<Int64>()
        if (n == 0) {
            return ""
        }
        let hundreds = n / 100
        let rest = n % 100
        var result = ""
        if (hundreds > 0) {
            result = this.NUMBER[hundreds] + " HUNDRED"
            if (rest > 0) {
                result = result + " AND "
            }
        }
        if (rest > 0) {
