        for (i in 0..groups.size) {
            let group = groups[i]
            let part = this.trans_three(group)
            let magnitudeIndex = groups.size - i - 1
            let suffix = this.parse_more(magnitudeIndex)
            if (part != "") {
                if (result != "") {
                    result = result + " "
                }
                result = result + part
