class NumberWordFormatter {

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        let value = x ?? ""
        return this.format_string(value)
    }

    public func format_string(x: String): String {
        if (x == "") {
            return "INVALID"
        }

        let parts = x.split(".")
        let integerPart = parts[0].trim()
        let decimalPart = if (parts.size > 1) { parts[1].trim() } else { "" }

        var result = ""
        if (integerPart != "0" && integerPart != "") {
            result = this.trans_integer(integerPart)
        } else {
            result = "ZERO"
        }

        if (decimalPart != "") {
            result = result + " POINT " + this.trans_decimal(decimalPart)
        }

        return result + " ONLY"
    }

    public func trans_two(s: String): String {
        let n = s.parseOr("0") as Int64
        if (n == 0) {
            return ""
        } else if (n < 10) {
            return this.NUMBER[n.toInt()]
        } else if (n < 20) {
            return this.NUMBER_TEEN[n - 10.toInt()]
        } else {
            let tens = n / 10
            let ones = n % 10
            let tensWord = this.NUMBER_TEN[tens.toInt() - 1]
            if (ones == 0) {
                return tensWord
            } else {
                return tensWord + " " + this.NUMBER[ones.toInt()]
            }
        }
    }

    public func trans_three(s: String): String {
        let n = s.parseOr("0") as Int64
        if (n == 0) {
            return ""
        }
        if (n < 100) {
            return this.trans_two(s)
        } else {
            let hundreds = n / 100
            let remainder = n % 100
            let hundredWord = this.NUMBER[hundreds.toInt()] + " HUNDRED"
            if (remainder == 0) {
                return hundredWord
            } else {
                let rest = this.trans_two(remainder.toString())
                return hundredWord + " AND " + rest
            }
        }
    }

    public func parse_more(i: Int64): String {
        if (i < 0 || i >= this.NUMBER_MORE.size) {
            return ""
        }
        return this.NUMBER_MORE[i.toInt()]
    }

    private func trans_integer(s: String): String {
        let numStr = s.trim()
        if (numStr == "0") {
            return "ZERO"
        }

        while (numStr.length > 1 && numStr[0] == '0') {
            // remove leading zeros
            numStr = numStr.substring(1)
        }

        let length = numStr.length
        let blocks = ArrayList<Array<String>>()
        var temp = ""

        // Process from right to left, group by 3 digits
        for (i in (length - 1)..-1:-1) {
            temp = numStr[i] + temp
            if (temp.length == 3 || i == 0) {
                blocks.add([temp], at: 0)
                temp = ""
            }
        }

        var result = ""
        let blockCount = blocks.size

        for (i in 0..blockCount) {
            let block = blocks[i]
            let chunk = block[0]
            let words = this.trans_three(chunk)
            if (words != "") {
                let magnitude = blockCount - i - 1
                let suffix = this.parse_more(magnitude.toLong())
                if (suffix != "") {
                    result = result + words + " " + suffix + " "
                } else {
                    result = result + words + " "
                }
            }
        }

        return result.trim()
    }

    private func trans_decimal(s: String): String {
        var result = ""
        for (i in 0..s.length) {
            let digit = s[i]
            let index = digit - '0'
            result = result + this.NUMBER[index.toInt()]
            if (i < s.length - 1) {
                result = result + " "
            }
        }
        return result
    }
}

