    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        let value = x ?? ""
        return this.format_string(value)
    }

    public func format_string(x: String): String {
        if (x == "") {
            return "ZERO ONLY"
        }

        let parts = x.split(".")
        let integerPart = parts[0].strip()
        let decimalPart = if (parts.size > 1) { parts[1].strip() } else { "" }

        var result = ""
        if (integerPart == "0" || integerPart == "") {
            result = "ZERO"
        } else {
            result = this.process_integer(integerPart)
        }

        if (decimalPart != "" && decimalPart != "0") {
            let decimalWords = this.process_integer(decimalPart)
            result = result + " POINT " + decimalWords
        }

        return result + " ONLY"
    }

    private func process_integer(numStr: String): String {
        let n = numStr.size
        var result = ""
        var groupCount = 0

        for (i in 0..n by 3) {
            let start = n - (groupCount + 1) * 3
            let end = n - groupCount * 3
            let chunkStart = if (start < 0) { 0 } else { start }
            let chunk = numStr.slice(chunkStart, end)

            if (chunk != "000") {
                let chunkWords = this.trans_three(chunk)
                let suffix = this.parse_more(groupCount)
                result = chunkWords + 
                         if (suffix != "") { " " + suffix } else { "" } + 
                         if (result != "") { " " + result } else { "" }
            }
            groupCount = groupCount + 1
        }

        return result
    }

    public func trans_two(s: String): String {
        let n = int.parse(s)
        if (n == 0) {
            return ""
        } else if (n < 10) {
            return this.NUMBER[n]
        } else if (n < 20) {
            return this.NUMBER_TEEN[n - 10]
        } else {
            let tens = n / 10
            let ones = n % 10
            return this.NUMBER_TEN[tens - 1] + 
                   if (ones != 0) { " " + this.NUMBER[ones] } else { "" }
        }
    }

    public func trans_three(s: String): String {
        let sTrim = s.stripStart("0")
        if (sTrim == "") {
            return "ZERO"
        }

        if (sTrim.size == 1) {
            return this.NUMBER[int.parse(sTrim)]
        } else if (sTrim.size == 2) {
            return this.trans_two(sTrim)
        }

        let hundreds = int.parse(s.slice(0, 1))
        let remainder = s.slice(1, 3).stripStart("0")

        if (hundreds == 0) {
            return this.trans_two(remainder)
        }

        let hundredWord = this.NUMBER[hundreds] + " HUNDRED"
        if (remainder == "") {
            return hundredWord
        }

        let rest = if (int.parse(remainder) < 10) {
            this.NUMBER[int.parse(remainder)]
        } else {
            this.trans_two(remainder)
        }

        return hundredWord + " AND " + rest
    }

    public func parse_more(i: Int64): String {
        if (i < 0 || i >= this.NUMBER_MORE.size) {
            return ""
        }
        return this.NUMBER_MORE[i]
    }
}

