    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        let num_str = x ?? ""
        if (num_str == "") {
            return "ZERO ONLY"
        }
        return format_string(num_str)
    }

    public func format_string(x: String): String {
        var num = x.trim()
        if (num == "") {
            return "ZERO ONLY"
        }

        // Handle decimal part
        let parts = num.split(".")
        let integer_part = parts[0]
        let decimal_part = if (parts.size > 1) { parts[1] } else { "" }

        var result = ""
        if (integer_part == "0" || integer_part == "") {
            result = "ZERO"
        } else {
            result = trans_integer(integer_part)
        }

        if (decimal_part != "" && decimal_part != "0") {
            result = result + " AND CENTS " + trans_integer(decimal_part) + " ONLY"
        } else {
            result = result + " ONLY"
        }

        return result
    }

    public func trans_two(s: String): String {
        var num = s.padStart(2, '0')
        let a = num[0] - '0'
        let b = num[1] - '0'
        if (a == 0) {
            return NUMBER[b]
        } else if (a == 1) {
            return NUMBER_TEEN[b]
        } else {
            if (b == 0) {
                return NUMBER_TEN[a]
            } else {
                return "${NUMBER_TEN[a]} ${NUMBER[b]}"
            }
        }
    }

    public func trans_three(s: String): String {
        var num = s.padStart(3, '0')
        let a = num[0] - '0'
        let bc = "${num[1]}${num[2]}"
        let rest = trans_two(bc)
        if (a == 0) {
            return rest
        } else {
            if (rest != "") {
                return "${NUMBER[a]} HUNDRED AND ${rest}"
            } else {
                return "${NUMBER[a]} HUNDRED"
            }
        }
    }

    private func trans_integer(s: String): String {
        var num = s
        if (num.startsWith("-")) {
            num = num.substring(1)
        }
        num = num.trimStart('0')
        if (num == "") {
            return "ZERO"
        }

        var result = ""
        var part_count = 0

        // Process from right to left in groups of 3
        for (i in num.size downTo 1 step 3) {
            let start = if (i >= 3) { i - 3 } else { 0 }
            let group = num.substring(start, i)
            let group_words = trans_three(group)

            if (group_words != "") {
                let suffix = parse_more(part_count)
                if (suffix != "") {
                    result = "${group_words} ${suffix} ${result}".trim()
                } else {
                    result = "${group_words} ${result}".trim()
                }
            }
            part_count = part_count + 1
        }

        return result.trim()
    }

    public func parse_more(i: Int64): String {
        if (i < NUMBER_MORE.size) {
            return NUMBER_MORE[i]
        } else {
            return ""
        }
    }
}

