        >>> game.move('a')   
        false
        >>> game.move('s') 
        false
        >>> game.move('d') 
        true
        */
        let d_row: Int64 = if (direction == "w") { -1 } 
                      else_if (direction == "s") { 1 } 
                      else_if (direction == "a") { 0 } 
                      else_if (direction == "d") { 0 } 
                      else { 0 }
        let d_col: Int64 = if (direction == "w") { 0 } 
                      else_if (direction == "s") { 0 } 
                      else_if (direction == "a") { -1 } 
                      else_if (direction == "d") { 1 } 
                      else { 0 }

        if (d_row == 0 && d_col == 0) {
            return check_win()
        }

        let new_row = player_row + d_row
        let new_col = player_col + d_col

        // Check bounds
        if (new_row < 0 || new_row >= map.size || new_col < 0 || new_col >= map[new_row].size) {
            return check_win()
        }

        // Check wall
        if (map[new_row][new_col] == "#") {
            return check_win()
        }

        // Check if there is a box
        var box_index = -1
        for (i in 0..boxes.size) {
            if (boxes[i][0] == new_row && boxes[i][1] == new_col) {
                box_index = i
                break
            }
        }

        if (box_index != -1) {
            // Try to push the box
            let push_row = new_row + d_row
            let push_col = new_col + d_col

            // Check bounds for push
            if (push_row < 0 || push_row >= map.size || push_col < 0 || push_col >= map[push_row].size) {
                return check_win()
            }

            // Check wall or another box
            if (map[push_row][push_col] == "#" || 
                any_box_at(push_row, push_col)) {
                return check_win()
            }

            // Move the box
            boxes[box_index][0] = push_row
            boxes[box_index][1] = push_col
        }

        // Move the player
        player_row = new_row
        player_col = new_col

        return check_win()
    }

    private func any_box_at(row: Int64, col: Int64): Bool {
        for (box in boxes) {
            if (box[0] == row && box[1] == col) {
                return true
            }
        }
        return false
    }
