        var on_target = 0
        for (box in boxes) {
            for (target in targets) {
                if (box[0] == target[0] && box[1] == target[1]) {
                    on_target += 1
                    break
                }
            }
        }
        is_game_over = (on_target == target_count)
        return is_game_over
    }

    public func move(direction: String): Bool {
        let d_row: Int64 = if (direction == "w") { -1 } else if (direction == "s") { 1 } else { 0 }
        let d_col: Int64 = if (direction == "a") { -1 } else if (direction == "d") { 1 } else { 0 }

        let new_row = player_row + d_row
        let new_col = player_col + d_col
        let next_row = new_row + d_row
        let next_col = new_col + d_col

        // Check if new position is out of bounds
        if (new_row < 0 || new_row >= map.size || new_col < 0 || new_col >= map[new_row].size) {
            return check_win()
        }

        let new_cell = map[new_row][new_col]
        if (new_cell == "#") {
            return check_win()
        }

        var box_index: ?Int64 = None<Int64>
        for (i in 0..boxes.size) {
            if (boxes[i][0] == new_row && boxes[i][1] == new_col) {
                box_index = Some<Int64>(i)
                break
            }
        }

        if (box_index != None<Int64>) {
            // Try to push the box
            let idx = box_index.getOrThrow()
            if (next_row < 0 || next_row >= map.size || next_col < 0 || next_col >= map[next_row].size) {
                return check_win()
