            boxes[idx][0] = next_row
            boxes[idx][1] = next_col
        }

        // Move player
        player_row = new_row
        player_col = new_col
        return check_win()
    }

    private func map_contains_box(row: Int64, col: Int64): Bool {
        for (box in boxes) {
            if (box[0] == row && box[1] == col) {
