class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        let regex = Regex("((?<!Mr)\\.|\\?)\\s+")
        let parts = regex.split(sentences_string.strip())
        let sentences = ArrayList<String>()

        for (i in 0..parts.size) {
            let part = parts[i]
            if (part.size == 0) {
                continue
            }
            // Re-add the terminal punctuation if not the last part
            if (i < parts.size - 1) {
                let lastChar = part.runes().last() ?? ' '
