class SQLQueryBuilder {

    public static func select(table: String, columns!: ArrayList<String> = ArrayList<String>(['*']), where_condition!: Option<HashMap<String, String>> = None): String {
        var query = "SELECT "

        for (i in 0..columns.size) {
            query = query + columns[i]
            if (i < columns.size - 1) {
                query = query + ", "
            }
        }

        query = query + " FROM " + table

        if (where_condition != None) {
            let cond = where_condition.getOrThrow()
            var first = true
            query = query + " WHERE "
            for (entry in cond) {
                if (!first) {
                    query = query + " AND "
                }
                query = query + entry.key + "='" + entry.value + "'"
                first = false
            }
        }

        return query
    }

    public static func insert(table: String, data: HashMap<String, String>): String {
        var columns = ""
        var values = ""
        var first = true

        for (entry in data) {
            if (!first) {
                columns = columns + ", "
                values = values + ", "
            }
            columns = columns + entry.key
            values = values + "'" + entry.value + "'"
            first = false
        }

        return "INSERT INTO " + table + " (" + columns + ") VALUES (" + values + ")"
    }

    public static func delete(table: String, where_condition!: Option<HashMap<String, String>> = None): String {
        var query = "DELETE FROM " + table

        if (where_condition != None) {
            let cond = where_condition.getOrThrow()
            var first = true
            query = query + " WHERE "
            for (entry in cond) {
                if (!first) {
                    query = query + " AND "
                }
                query = query + entry.key + "='" + entry.value + "'"
                first = false
            }
        }

        return query
    }

    public static func update(table: String, data: HashMap<String, String>, where_condition!: Option<HashMap<String, String>> = None): String {
        var query = "UPDATE " + table + " SET "

        var first = true
        for (entry in data) {
            if (!first) {
                query = query + ", "
            }
            query = query + entry.key + "='" + entry.value + "'"
