import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        let n = data.size
        if (n == 0) {
            return 0.0
        }
        let sorted = ArrayList<Int64>(data)
        sort(sorted)
        let mid = n / 2
        if (n % 2 == 0) {
            return (sorted[mid - 1] + sorted[mid]) / 2.0
        } else {
            return sorted[mid] as Float64
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let freq = HashMap<Int64, Int64>()
        for (x in 0..data.size) {
            let val = data[x]
            if (freq.contains(val)) {
                freq[val] = freq[val] + 1
            } else {
                freq[val] = 1
            }
        }
        var maxFreq = 0
        for (count in freq.values()) {
            if (count > maxFreq) {
                maxFreq = count
            }
        }
        let modes = ArrayList<Int64>()
        for (kv in freq.pairs()) {
            if (kv.value == maxFreq) {
                modes.add(kv.key)
            }
        }
        sort(modes)
        return modes
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) {
            return None<Float64>
        }
        var sum = 0.0
        for (i in 0..data.size) {
            sum = sum + (data[i] as Float64)
        }
        return Some<Float64>(sum / (data.size as Float64))
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let m = mean(data) ?? 0.0
        if (data.size == 0) {
            return None<Float64>
        }
        var sum_sq = 0.0
        for (i in 0..data.size) {
            let diff = (data[i] as Float64) - m
            sum_sq = sum_sq + diff * diff
        }
        let variance = sum_sq / (data.size as Float64)
        return Some<Float64>(sqrt(variance))
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size != y.size || x.size == 0) {
            return None<Float64>
        }
        let x_mean = mean(x) ?? 0.0
        let y_mean = mean(y) ?? 0.0

        var numerator = 0.0
        var x_var_sum = 0.0
        var y_var_sum = 0.0

        for (i in 0..x.size) {
            let dx = (x[i] as Float64) - x_mean
            let dy = (y[i] as Float64) - y_mean
            numerator = numerator + dx * dy
            x_var_sum = x_var_sum + dx * dx
            y_var_sum = y_var_sum + dy * dy
        }

        if (x_var_sum == 0.0 || y_var_sum == 0.0) {
            return None<Float64>
        }

        let denominator = sqrt(x_var_sum * y_var_sum)
        return Some<Float64>(numerator / denominator)
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let n = data.size
        let result = ArrayList<ArrayList<Float64>>()
        for (i in 0..n) {
            result.add(ArrayList<Float64>())
            for (j in 0..n) {
                let corr = correlation(data[i], data[j])
                result[i].add(corr ?? 0.0)
            }
        }
        return result
    }

