class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        if (data.size == 0) {
            return 0.0
        }
        var sorted = ArrayList<Int64>(data)
        sort(sorted)
        let n = sorted.size
        if (n % 2 == 0) {
            return (sorted[n / 2 - 1] + sorted[n / 2]) / 2.0
        } else {
            return sorted[n / 2] as Float64
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        if (data.size == 0) {
            return ArrayList<Int64>([])
        }
        let freq = HashMap<Int64, Int64>()
        for (x in 0..data.size) {
            let value = data[x]
            if (freq.contains(value)) {
                freq[value] = freq[value] + 1
            } else {
                freq.add(value, 1)
            }
        }
        var max_count = 0
        for (count in freq.values()) {
            if (count > max_count) {
                max_count = count
            }
        }
        let modes = ArrayList<Int64>()
        for ((value, count) in freq.entries()) {
            if (count == max_count) {
                modes.add(value)
            }
        }
        sort(modes)
        return modes
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) {
            return None<Float64>
        }
        var sum = 0.0
        for (i in 0..data.size) {
            sum = sum + (data[i] as Float64)
        }
        return Some(sum / (data.size as Float64))
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let m = Statistics3.mean(data)
        if (m is None<Float64>) {
            return None<Float64>
        }
        let mean_val = m.getOrThrow()
        var variance = 0.0
        for (i in 0..data.size) {
            let diff = (data[i] as Float64) - mean_val
            variance = variance + diff * diff
        }
        variance = variance / (data.size as Float64)
        return Some(sqrt(variance))
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size != y.size || x.size == 0) {
            return None<Float64>
        }
        let mx = Statistics3.mean(x)
        let my = Statistics3.mean(y)
        if (mx is None<Float64> || my is None<Float64>) {
            return None<Float64>
        }
        let m_x = mx.getOrThrow()
        let m_y = my.getOrThrow()
        var numerator = 0.0
        var sum_x_sq = 0.0
        var sum_y_sq = 0.0
        for (i in 0..x.size) {
            let dx = (x[i] as Float64) - m_x
            let dy = (y[i] as Float64) - m_y
            numerator = numerator + dx * dy
            sum_x_sq = sum_x_sq + dx * dx
            sum_y_sq = sum_y_sq + dy * dy
        }
        if (sum_x_sq == 0.0 || sum_y_sq == 0.0) {
            return None<Float64>
        }
        let denominator = sqrt(sum_x_sq * sum_y_sq)
        return Some(numerator / denominator)
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        if (data.size == 0) {
            return ArrayList<ArrayList<Float64>>()
        }
        let n = data.size
        let result = ArrayList<ArrayList<Float64>>()
        for (i in 0..n) {
            result.add(ArrayList<Float64>(n))
            for (j in 0..n) {
                let corr = Statistics3.correlation(data[i], data[j])
                result[i][j] = corr.getOrThrow() ?? 1.0
            }
        }
        return result
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let m = Statistics3.mean(data)
        let std = Statistics3.standard_deviation(data)
        if (m is None<Float64> || std is None<Float64>) {
            return None<ArrayList<Float64>>
        }
        let mean_val = m.getOrThrow()
        let std_val = std.getOrThrow()
        let z_scores = ArrayList<Float64>()
        if (std_val == 0.0) {
            for (_ in 0..data.size) {
                z_scores.add(0.0)
            }
        } else {
            for (i in 0..data.size) {
                z_scores.add(((data[i] as Float64) - mean_val) / std_val)
            }
        }
        return Some(z_scores)
    }
}

