        } else {
            let mid1 = sorted_data[n / 2 - 1] as Float64
            let mid2 = sorted_data[n / 2] as Float64
            return (mid1 + mid2) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let freq_map = HashMap<Int64, Int64>()
        for (x in data) {
            let count = freq_map.get(x) ?? 0
            freq_map.add(x, count + 1)
        }

        var max_count = 0
        for (count in freq_map.values()) {
            if (count > max_count) {
                max_count = count
            }
        }

        let modes = ArrayList<Int64>()
        for ((value, count) in freq_map.entries()) {
            if (count == max_count) {
                modes.add(value)
            }
        }

        sort(modes)
        return modes
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) {
            return None<Float64>
        }
        var sum = 0L
        for (x in data) {
            sum += x
        }
        return Some<Float64>(sum as Float64 / data.size as Float64)
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let m = mean(data)
        if (m == None<Float64>) {
            return None<Float64>
        }
        let mean_val = m.getOrThrow()
        var variance = 0.0
        for (x in data) {
            let diff = x as Float64 - mean_val
            variance += diff * diff
        }
        variance /= data.size as Float64
        return Some<Float64>(sqrt(variance))
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        let n = x.size
        if (n != y.size || n == 0) {
            return None<Float64>
        }

        let x_mean_opt = mean(x)
        let y_mean_opt = mean(y)
        if (x_mean_opt == None<Float64> || y_mean_opt == None<Float64>) {
            return None<Float64>
        }
        let x_mean = x_mean_opt.getOrThrow()
        let y_mean = y_mean_opt.getOrThrow()

        var cov = 0.0
        var var_x = 0.0
        var var_y = 0.0
        for (i in 0..n) {
            let dx = x[i] as Float64 - x_mean
            let dy = y[i] as Float64 - y_mean
            cov += dx * dy
            var_x += dx * dx
            var_y += dy * dy
        }

        if (var_x == 0.0 || var_y == 0.0) {
            return None<Float64>
        }

        let corr = cov / (sqrt(var_x) * sqrt(var_y))
        return Some<Float64>(corr)
    }

