        if (n == 0) {
            return ArrayList<ArrayList<Float64>>()
        }
        let row_len = data[0].size
        for (row in data) {
            if (row.size != row_len) {
                // Not rectangular – return empty for safety
                return ArrayList<ArrayList<Float64>>()
            }
        }

        let matrix = ArrayList<ArrayList<Float64>>()
        for (i in 0..n) {
            let row = ArrayList<Float64>()
            for (j in 0..n) {
                let corr = correlation(data[i], data[j])
                let val = if (corr != None<Float64>) { corr.getOrThrow() } else { 0.0 }
                row.add(val)
            }
            matrix.add(row)
        }
        return matrix
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
