                let value = stock.price * stock.quantity
                this.cash_balance += value
                owned_stock.quantity -= stock.quantity
                if (owned_stock.quantity == 0) {
                    this.portfolio.remove(at: index)
                }
                return true
            }
        }
        return false
    }

