            return false
        }
        cash_balance = cash_balance - total_cost
        add_stock(stock)
        return true
    }

    public func sell_stock(stock: Stock): Bool {
        for (i in 0..portfolio.size) {
            let owned = portfolio[i]
            if (owned.name == stock.name && owned.price == stock.price) {
                if (owned.quantity < stock.quantity) {
                    return false
                }
                let value = stock.price * stock.quantity
                cash_balance = cash_balance + value
                owned.quantity = owned.quantity - stock.quantity
                if (owned.quantity == 0) {
                    portfolio.remove(at: i)
                }
                return true
            }
        }
        return false
    }

    public func calculate_portfolio_value(): Float64 {
        var total: Float64 = 0.0
        for (i in 0..portfolio.size) {
            total = total + get_stock_value(portfolio[i])
        }
        return total + cash_balance
    }

    public func get_portfolio_summary(): (Float64, ArrayList<HashMap<String, Any>>) {
        let total_value = calculate_portfolio_value()
        let summary = ArrayList<HashMap<String, Any>>()
        for (i in 0..portfolio.size) {
            let stock = portfolio[i]
            let stock_value = get_stock_value(stock)
            let stock_info = HashMap<String, Any>([("name", stock.name), ("value", stock_value)])
            summary.add(stock_info)
        }
        return (total_value, summary)
    }

    public func get_stock_value(stock: Stock): Float64 {
        return stock.price * stock.quantity
    }
}

