    var target_temperature: Float64
    var mode: String

    public init(current_temperature: Float64, target_temperature: Float64, mode: String) {
        this.current_temperature = current_temperature
        this.target_temperature = target_temperature
        this.mode = mode
    }

    public func get_target_temperature(): Float64 {
        return this.target_temperature
    }

    public func set_target_temperature(temperature: Float64): Unit {
        this.target_temperature = temperature
    }

    public func get_mode(): String {
        return this.mode
    }

    public func set_mode(mode: String): Bool {
        if (mode == "heat" || mode == "cool") {
            this.mode = mode
            return true
        } else {
            return false
        }
    }

    public func auto_set_mode(): Unit {
        if (this.current_temperature < this.target_temperature) {
            this.mode = "heat"
        } else {
            this.mode = "cool"
        }
    }

    public func auto_check_conflict(): Bool {
        let heating_required = this.current_temperature < this.target_temperature
        let cooling_required = this.current_temperature > this.target_temperature

        if ((heating_required && this.mode == "heat") || 
            (cooling_required && this.mode == "cool") ||
            (!heating_required && !cooling_required)) { // at target temp
            return true
        } else {
            this.auto_set_mode()
            return false
        }
    }

    public func simulate_operation(): Int64 {
        this.auto_set_mode()
        var time: Int64 = 0
        let delta: Float64 = 0.5

        while (abs(this.current_temperature - this.target_temperature) > 1e-6) {
            if (this.mode == "heat") {
                this.current_temperature = this.current_temperature + delta
            } else {
                this.current_temperature = this.current_temperature - delta
            }
            time = time + 1
        }

        return time
    }
}

