            this.mode = "heat"
        } else {
            this.mode = "cool"
        }
    }

    public func auto_check_conflict(): Bool {
        let heating_needed = this.current_temperature < this.target_temperature
        let cooling_needed = this.current_temperature > this.target_temperature

        if ((heating_needed && this.mode == "heat") || (cooling_needed && this.mode == "cool")) {
            return true
        }

        // Adjust mode if conflicting
        auto_set_mode()
        return false
    }

    public func simulate_operation(): Int64 {
        auto_set_mode()
        var time: Int64 = 0
        let delta: Float64 = 0.5

        while (abs(this.current_temperature - this.target_temperature) > 1e-6) {
            if (this.mode == "heat") {
                this.current_temperature = this.current_temperature + delta
                if (this.current_temperature > this.target_temperature) {
                    this.current_temperature = this.target_temperature
                }
            } else {
                this.current_temperature = this.current_temperature - delta
                if (this.current_temperature < this.target_temperature) {
                    this.current_temperature = this.target_temperature
                }
            }
            time = time + 1
        }

        return time
    }
}

