                return Some<String>(board[i][0])
            }
        }

        // Check columns
        for (j in 0..n) {
            let col = ArrayList<String>()
            for (i in 0..n) {
                col.add(board[i][j])
            }
            if (col[0] != " " && all_same(col)) {
                return Some<String>(col[0])
            }
        }

        // Check main diagonal
        let diag1 = ArrayList<String>()
        for (i in 0..n) {
            diag1.add(board[i][i])
        }
        if (diag1[0] != " " && all_same(diag1)) {
            return Some<String>(diag1[0])
        }

        // Check anti-diagonal
        let diag2 = ArrayList<String>()
        for (i in 0..n) {
            diag2.add(board[i][n - 1 - i])
        }
        if (diag2[0] != " " && all_same(diag2)) {
            return Some<String>(diag2[0])
        }

        return None<String>
    }

    private func all_same(list: ArrayList<String>): Bool {
        let first = list[0]
        if (first == " ") {
            return false
        }
        for (i in 1..list.size) {
            if (list[i] != first) {
                return false
            }
        }
        return true
    }

