        Check if there is a winner on the board in rows, columns and diagonals three directions
        :return: Option<String>, the mark of the winner ('X' or 'O'), or None if there is no winner yet
        >>> moves = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 0]), ArrayList<Int64>([2, 0]), ArrayList<Int64>([1, 1]), ArrayList<Int64>([2, 1]), ArrayList<Int64>([1, 2])])
        >>> for move in moves:
        ...     ttt.make_move(move[0], move[1])
        >>> ttt.check_winner()
        'X'
        */

        // Check rows
        for (i in 0..3) {
            let row = this.board[i]
            if (row[0] != " " && row[0] == row[1] && row[1] == row[2]) {
                return Some<String>(row[0])
            }
        }

        // Check columns
        for (j in 0..3) {
            if (this.board[0][j] != " " && 
                this.board[0][j] == this.board[1][j] && 
                this.board[1][j] == this.board[2][j]) {
                return Some<String>(this.board[0][j])
            }
        }

        // Check diagonals
        if (this.board[0][0] != " " && 
            this.board[0][0] == this.board[1][1] && 
            this.board[1][1] == this.board[2][2]) {
            return Some<String>(this.board[0][0])
        }
        if (this.board[0][2] != " " && 
            this.board[0][2] == this.board[1][1] && 
            this.board[1][1] == this.board[2][0]) {
            return Some<String>(this.board[0][2])
        }

        return None<String>
    }

    public func is_board_full(): Bool {
        /*
        Check if the game board is completely filled.
        :return: Bool, indicating whether the game board is full or not
        >>> ttt.is_board_full()
        false
        */
        for (i in 0..3) {
            for (j in 0..3) {
                if (this.board[i][j] == " ") {
                    return false
                }
            }
        }
        return true
    }
}

import std.collection.*
