class TicTacToe {
    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(N!: Int64 = 3) {
        this.board = ArrayList<ArrayList<String>>()
        for (_ in 0..N) {
            let row = ArrayList<String>()
            for (_ in 0..N) {
                row.add(" ")
            }
            this.board.add(row)
        }
        this.current_player = "X"
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if (row < 0 || row >= this.board.size || col < 0 || col >= this.board[0].size) {
            return false
        }
        if (this.board[row][col] != " ") {
            return false
        }
        this.board[row][col] = this.current_player
        this.current_player = if (this.current_player == "X") { "O" } else { "X" }
        return true
    }

    public func check_winner(): Option<String> {
        let n = this.board.size

        // Check rows
        for (i in 0..n) {
            let row = this.board[i]
            if (row[0] != " " && all_equal(row)) {
                return Some<String>(row[0])
            }
        }

        // Check columns
        for (j in 0..n) {
            let col = ArrayList<String>()
            for (i in 0..n) {
                col.add(this.board[i][j])
            }
            if (col[0] != " " && all_equal(col)) {
                return Some<String>(col[0])
            }
        }

        // Check main diagonal
        let main_diag = ArrayList<String>()
        for (i in 0..n) {
            main_diag.add(this.board[i][i])
        }
        if (main_diag[0] != " " && all_equal(main_diag)) {
            return Some<String>(main_diag[0])
        }

        // Check anti-diagonal
        let anti_diag = ArrayList<String>()
        for (i in 0..n) {
            anti_diag.add(this.board[i][n - 1 - i])
        }
        if (anti_diag[0] != " " && all_equal(anti_diag)) {
            return Some<String>(anti_diag[0])
        }

        return None<String>
    }

    public func is_board_full(): Bool {
        for (i in 0..this.board.size) {
            for (j in 0..this.board[i].size) {
                if (this.board[i][j] == " ") {
                    return false
                }
            }
        }
        return true
    }

    // Helper function to check if all elements in a list are equal
    private func all_equal(lst: ArrayList<String>): Bool {
        let first = lst[0]
        for (i in 1..lst.size) {
            if (lst[i] != first) {
                return false
            }
        }
        return true
    }
}

