import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs
import std.collection.*

class TriCalculator {
    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        let rad = x * PI / 180.0
        return taylor(rad, 50)
    }

    public func factorial(a: Int64): Decimal {
        let one = Decimal(1)
        if (a == 0 || a == 1) {
            return one
        }
        var result = one
        for (i in 2..a+1) {
            result = result * Decimal(i)
        }
        return result
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        var result = 0.0
        var term = 1.0
        var sign = 1.0
        var power = 1.0
        var fact: Decimal = Decimal(1)

        for (i in 0..n+1) {
            if (i == 0) {
                term = 1.0
            } else {
                sign = sign * -1.0
                power = power * x * x
                fact = factorial(2 * i)
                term = sign * power / fact.toDouble()
            }
            result = result + (if (i == 0) { 1.0 } else { term })
        }
        return result
    }

    public func sin(x: Float64): Float64 {
        let rad = x * PI / 180.0
        var result = 0.0
        var sign = 1.0
        for (i in 0..50) {
            let numerator = pow(rad, 2 * i + 1)
            let denominator = factorial(2 * i + 1).toDouble()
            result = result + sign * numerator / denominator
            sign = sign * -1.0
        }
        return result
    }

    public func tan(x: Float64): Option<Float64> {
        let cos_val = cos(x)
        if (abs(cos_val - 0.0) < 0.000001) {
            return None<Float64>
        }
        return Some<Float64>(sin(x) / cos_val)
    }

    // Helper function for power calculation
    private func pow(base: Float64, exp: Int64): Float64 {
        if (exp == 0) {
            return 1.0
        }
        var result = 1.0
        var e = exp
        var b = base
        while (e > 0) {
            if (e % 2 == 1) {
                result = result * b
            }
            b = b * b
            e = e / 2
        }
        return result
    }
}

