class TwentyFourPointGame {
    var nums: ArrayList<Int64>

    public init() {
        this.nums = ArrayList<Int64>()
    }

    public func _generate_cards(): Unit {
        let rand = Random()
        this.nums.clear()
        for (i in 0..4) {
            this.nums.add((rand.next() % 9 + 1) as Int64)
        }
    }

    public func get_my_cards(): ArrayList<Int64> {
        this._generate_cards()
        return this.nums
    }

    public func answer(expression: String): Bool {
        // Check if all characters in the expression are valid (digits, operators, parentheses, spaces)
        for (r in expression.runes()) {
            if !(r.isAsciiNumber() || r in [r'+', r'-', r'*', r'/', r'(', r')', r' ']) {
                return false
            }
        }

        // Validate that all numbers used are from the current cards
        var available = HashMap<Int64, Int64>()
        for (num in this.nums) {
            let count = available.get(num) ?? 0
            available.add(num, count + 1)
        }

        var used = HashMap<Int64, Int64>()
        var i = 0
        while (i < expression.size) {
            if (expression[i].isAsciiNumber()) {
                var start = i
                while (i < expression.size && expression[i].isAsciiNumber()) {
                    i += 1
                }
                let num = Int64.parse(expression[start..i])
                let count = used.get(num) ?? 0
                used.add(num, count + 1)
            } else {
                i += 1
            }
        }

        for (entry in used.entries()) {
            let num = entry.key
            let used_count = entry.value
            let available_count = available.get(num) ?? 0
            if (used_count > available_count) {
                return false
            }
        }

        return this.evaluate_expression(expression)
    }

    public func evaluate_expression(expression: String): Bool {
        try {
            let parser = Parser(expression)
            let result = parser.parse()
            return result == 24
        } catch (_) {
            return false
        }
    }
}

