        /*
        get the scheme of the URL
        :return: Option<String>, If successful, return the scheme of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_scheme()
        "https"
        */
        let i = url.find("://")
        if (i == -1) {
            return None<String>
        }
        return Some<String>(url[0..i])
    }

    public func get_host(): Option<String> {
        /*
        Get the second part of the URL, which is the host domain name
        :return: Option<String>, If successful, return the host domain name of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_host()
        "www.baidu.com"
        */
        let scheme_end = url.find("://")
        if (scheme_end == -1) {
            return None<String>
        }
        let start = scheme_end + 3
        let rest = url[start..]
        let path_index = rest.find("/") ?? rest.size
        let query_index = rest.find("?") ?? rest.size
        let fragment_index = rest.find("#") ?? rest.size
        let end = min(min(path_index, query_index), fragment_index)
        if (end == 0) {
            return None<String>
        }
        return Some<String>(rest[0..end])
    }

    public func get_path(): Option<String> {
        /*
        Get the third part of the URL, which is the address of the resource
        :return: Option<String>, If successful, return the address of the resource of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_path()
        "/s?wd=aaa&rsv_spt=1#page"
        */
        let scheme_end = url.find("://")
        let start = if (scheme_end == -1) { 0 } else { scheme_end + 3 }
        let rest = url[start..]
        let host_end = rest.find("/") ?? rest.find("?") ?? rest.find("#") ?? rest.size
        if (host_end == rest.size) {
            return None<String>
        }
        return Some<String>(rest[host_end..])
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        /*
        Get the request parameters for the URL
        :return: Option<HashMap<String, String>>, If successful, return the request parameters of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_query_params()
        {"wd": "aaa", "rsv_spt": "1"}
        */
        let query_start = url.find("?")
        if (query_start == -1) {
            return None<HashMap<String, String>>
        }
        let fragment_start = url.find("#")
        let end = if (fragment_start == -1) { url.size } else { fragment_start }
        let query_str = url[query_start + 1..end]
        let pairs = query_str.split("&")
        let params = HashMap<String, String>([])
        for (pair in 0..pairs.size) {
            let kv = pairs[pair].split("=")
            if (kv.size == 2) {
                params.add(kv[0], kv[1])
            } else if (kv.size == 1 && kv[0].size > 0) {
                params.add(kv[0], "")
            }
        }
        return Some<HashMap<String, String>>(params)
    }

    public func get_fragment(): Option<String> {
        /*
        Get the fragment after '#' in the URL
        :return: Option<String>, If successful, return the fragment after '#' of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_fragment()
        "page"
        */
        let fragment_start = url.find("#")
        if (fragment_start == -1) {
            return None<String>
        }
        let fragment = url[fragment_start + 1..]
        if (fragment.size == 0) {
            return None<String>
        }
