        let path_or_query_or_frag = url.indexOf('/', at: start) ?? url.size
        let query = url.indexOf('?', at: start) ?? url.size
        let fragment = url.indexOf('#', at: start) ?? url.size
        let end = path_or_query_or_frag.min(query).min(fragment)
        if (start >= end) {
            return None<String>
        }
        return Some<String>(url[start..end])
    }

    public func get_path(): Option<String> {
        /*
        Get the third part of the URL, which is the address of the resource
        :return: Option<String>, If successful, return the address of the resource of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_path()
        "/s?wd=aaa&rsv_spt=1#page"
        */
        let scheme_end = url.indexOf("://")
        let start_pos = if (scheme_end == -1) { 0 } else { scheme_end + 3 }
        let host_end = url.indexOf('/', at: start_pos)
        if (host_end == -1) {
            return None<String>
        }
        return Some<String>(url[host_end..])
    }

