            return Some<HashMap<String, String>>(HashMap<String, String>([]))
        }
        let pairs = query_str.split('&')
        let params = HashMap<String, String>([])
        for (pair in pairs) {
            let eq = pair.indexOf('=')
            if (eq != -1) {
                let key = pair[0..eq]
                let value = pair[eq + 1..]
                params.add(key, value)
            } else {
                params.add(pair, "")
            }
        }
