class Words2Numbers {

    let numwords: HashMap<String, (Int64, Int64)>
    let units: ArrayList<String>
    let tens: ArrayList<String>
    let scales: ArrayList<String>
    let ordinal_words: HashMap<String, Int64>
    let ordinal_endings: ArrayList<(String, String)>

    public init() {
        this.numwords = HashMap<String, (Int64, Int64)>()
        this.units = ArrayList<String>(["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"])
        this.tens = ArrayList<String>(["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"])
        this.scales = ArrayList<String>(["hundred", "thousand", "million", "billion", "trillion"])

        this.numwords["and"] = (1, 0)
        for (idx in 0..this.units.size) {
            if (idx < this.units.size) {
                this.numwords[this.units[idx]] = (1, idx)
            }
        }
        for (idx in 0..this.tens.size) {
            if (idx < this.tens.size && !this.tens[idx].equals("")) {
                this.numwords[this.tens[idx]] = (1, idx * 10)
            }
        }
        for (idx in 0..this.scales.size) {
            if (idx < this.scales.size) {
                let scale = this.scales[idx]
                if (idx == 0) { // "hundred"
                    this.numwords[scale] = (100, 0)
                } else {
                    this.numwords[scale] = (Int64(10.0 ** (idx * 3)), 0)
                }
            }
        }

        this.ordinal_words = HashMap<String, Int64>([
            ("first", 1), ("second", 2), ("third", 3), ("fifth", 5),
            ("eighth", 8), ("ninth", 9), ("twelfth", 12)
        ])
        this.ordinal_endings = ArrayList<(String, String)>([
            ("ieth", "y"), ("th", "")
        ])
    }

    public func is_valid_input(textnum: String): Bool {
        let words = textnum.replace("-", " ").toLowerCase().split(" ")
        for (word in words) {
            let cleaned = word.trim()
            if (cleaned.equals("")) {
                continue
            }
            if (this.numwords.contains(cleaned)) {
                continue
            }
            if (this.ordinal_words.contains(cleaned)) {
                continue
            }
            var matched = false
            for (ending_pair in this.ordinal_endings) {
                let suffix = ending_pair[0]
                let root = ending_pair[1]
                if (cleaned.endsWith(suffix)) {
                    let base_word = cleaned.substring(0, cleaned.size - suffix.size) + root
                    if (this.units.contains(base_word) || this.tens.contains(base_word)) {
                        matched = true
                        break
                    }
                }
            }
            if (!matched) {
                return false
            }
        }
        return true
    }

    public func text2int(textnum: String): String {
        if (!this.is_valid_input(textnum)) {
            return "Invalid input"
        }

        let words = textnum.replace("-", " ").toLowerCase().split(" ")
        var current = 0
        var result = 0

        for (raw_word in words) {
            let word = raw_word.trim()
            if (word.equals("") || word.equals("and")) {
                continue
            }

            var num_value: Option<(Int64, Int64)> = None<(Int64, Int64)>
            if (this.numwords.contains(word)) {
                num_value = Some<(Int64, Int64)>(this.numwords[word])
            } else {
                for (ending_pair in this.ordinal_endings) {
                    let suffix = ending_pair[0]
                    let root = ending_pair[1]
                    if (word.endsWith(suffix)) {
                        let base_word = word.substring(0, word.size - suffix.size) + root
                        if (this.numwords.contains(base_word)) {
                            num_value = Some<(Int64, Int64)>(this.numwords[base_word])
                            break
                        }
                    }
                }
                if (this.ordinal_words.contains(word)) {
                    let val = this.ordinal_words[word]
                    num_value = Some<(Int64, Int64)>((1, val))
                }
            }

            match (num_value) {
                case Some(value) => {
                    let (scale, increment) = value
                    current = current * scale + increment
                    if (scale > 100) {
                        result += current
                        current = 0
                    }
                }
                case None => {}
            }
        }

        result += current
        return result.toString()
    }
}

